insert into public.content_translations (content_id,language_code,title,content) select 'e0bde541-7b08-5e1e-a909-c767fb484c5b','ar','FBS للمقاولات','{"footer":{"description":"نقدم مشاريع سكنية وتجارية في المملكة العربية السعودية مع التركيز على الجودة والموثوقية والقيمة طويلة الأمد.","companyTitle":"الشركة","projectsTitle":"المشاريع","connectTitle":"تواصل معنا","whoWeAre":"من نحن","visionMission":"الرؤية والرسالة","values":"قيمنا","residential":"السكني","commercial":"التجاري","sustainability":"الاستدامة","careers":"الوظائف","suppliers":"تسجيل الموردين","contact":"تواصل معنا","copyright":"FBS للمقاولات. جميع الحقوق محفوظة."},"language":{"english":"English","arabic":"العربية"}}' where not exists (select 1 from public.content_translations where content_id = 'e0bde541-7b08-5e1e-a909-c767fb484c5b' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select 'e0bde541-7b08-5e1e-a909-c767fb484c5b','src/contracting/site/i18n/{en,ar}.ts; src/contracting/site/pages/contact/ContactPage.tsx','{"en":{"loadingPage":"Loading page…","navigation":{"logo_t1":"FBS","logo_t2":"Contracting","home":"Home","aboutUs":"About Us","whoWeAre":"Who We Are","ceoMessage":"CEO Message","ourTeam":"Our Team","whyFbsContracting":"Why FBS Contracting?","visionMission":"Vision & Mission","saudiVision2030":"Saudi Vision 2030","coreValues":"Our Values","ourProjects":"Our Projects","residential":"Residential","commercial":"Commercial","sustainability":"Sustainability","environmentalResponsibility":"Environmental Responsibility","socialResponsibility":"Social Responsibility","economicResponsibility":"Economic Responsibility","continuousImprovement":"Continuous Improvement","businessContinuity":"Business Continuity","riskAssessmentManagement":"Risk Assessment and Management","businessImpactAnalysis":"Business Impact Analysis","planDevelopment":"Plan Development","recoveryRestoration":"Recovery and Restoration","leadershipAccountability":"Leadership and Accountability","careersTraining":"Careers & Training","careers":"Careers","training":"Training","supplierRegistration":"Supplier Registration","contact":"Contact","mainNavigationLabel":"Main navigation","openMenuLabel":"Open menu","menu":"Menu","close":"Close"},"home":{"hero":{"imageAlt":"Jawhart Al-Sahab residential architecture in Riyadh","statistics":{"heading":"FBS Contracting in numbers","approvalNotice":"Demo figures from the existing company artwork. Pending official client approval.","thousand":"K","billion":"B","currencyUnit":"SAR","labels":{"projectValue":"Project value","residentialProjects":"Residential projects","residentialUnits":"Residential units","builtUpArea":"Built-up area","commercialProjects":"Commercial projects","concreteWorks":"Concrete works","employees":"Employees"}},"eyebrow":"FBS Contracting","titleLine1":"Building with","titleLine2":"purpose.","description":"Delivering residential and commercial developments across Saudi Arabia through quality, reliability and a commitment to long-term value.","primaryCta":"Explore Projects","secondaryCta":"Discover FBS","location":"Kingdom of Saudi Arabia"},"companyIntroduction":{"eyebrow":"Who We Are","titleLine1":"A Vision That","titleLine2":"Shapes Reality.","description":"FBS Contracting Company is a leading construction company dedicated to delivering exceptional construction services. With a strong focus on quality, innovation, and client satisfaction, we have established ourselves as a trusted partner in the industry.","secondaryText":"We understand that every project is unique. Our commitment to excellence, safety, and close collaboration with clients guides us in bringing their visions to life.","cta":"Learn More About FBS"},"capabilities":{"eyebrow":"Company Services","titleLine1":"From concept","titleLine2":"to completion.","description":"We provide comprehensive services throughout the project lifecycle, from initial feasibility studies and concept design to construction works. Through partnerships with experts across disciplines, we offer an integrated approach to project planning and execution.","items":["Feasibility Study","Land Development","Design Management","Construction Works","Maintenance & Operations"]},"projectCategories":{"eyebrow":"Our Projects","titleLine1":"Built across two","titleLine2":"core sectors.","description":"Explore FBS Contracting projects across residential and commercial developments throughout Saudi Arabia.","residential":{"title":"Residential","description":"Integrated residential developments designed around quality, comfort and long-term value."},"commercial":{"title":"Commercial","description":"Commercial environments delivered with efficiency, precision and a clear understanding of business needs."}},"projectMap":{"selectedProjectLabel":"Selected Project","photoPinHint":"Select a project photo to explore its details.","photoPositionNote":"Photo positions and connectors are illustrative, not exact project coordinates.","projectSingular":"Project","projectPlural":"Projects","countryLabel":"Saudi Arabia","eyebrow":"Project Footprint","titleLine1":"Building across","titleLine2":"Saudi Arabia.","description":"Explore selected FBS Contracting projects across five regions of Saudi Arabia.","viewProject":"View Project","projects":{"riyadh":{"title":"Jawhart Al-Sahab","type":"Residential","location":"Riyadh"},"jeddah":{"title":"Nozol Khayala","type":"Residential","location":"Jeddah"},"madinah":{"title":"Nozol Al-Dar","type":"Residential","location":"Al Madinah Al Munawwarah"},"taif":{"title":"Malfa Al-Hawya","type":"Residential","location":"Taif"},"tabuk":{"title":"Malfa Tabuk Hills","type":"Residential","location":"Tabuk"}}},"vision2030":{"eyebrow":"Saudi Vision 2030","titleLine1":"Contributing to a","titleLine2":"growing Kingdom.","description":"FBS Contracting supports the Kingdom’s development ambitions by delivering projects that contribute to sustainable growth, stronger communities and long-term value.","cta":"Explore Saudi Vision 2030"},"values":{"eyebrow":"Our Values","titleLine1":"Values that guide","titleLine2":"how we build.","description":"Discover the six core values that guide FBS Contracting.","items":{"integrity":{"title":"Integrity","description":"We work with transparency, accountability and respect in every relationship."},"quality":{"title":"Quality","description":"We maintain a consistent focus on high standards across every stage of delivery."},"collaboration":{"title":"Collaboration","description":"We bring teams, disciplines and partners together around shared project goals."},"responsibility":{"title":"Responsibility","description":"We approach every project with care for people, communities and long-term impact."}}},"sustainability":{"eyebrow":"Sustainability","titleLine1":"Building with","titleLine2":"lasting responsibility.","description":"Our approach considers environmental, social and economic responsibility as part of creating long-term value through the projects we deliver.","cta":"Explore Sustainability","items":{"environmental":{"title":"Environmental Responsibility","description":"Supporting more responsible project practices with attention to resources, efficiency and long-term environmental impact."},"social":{"title":"Social Responsibility","description":"Creating value for people and communities through responsible delivery and collaborative project practices."},"economic":{"title":"Economic Responsibility","description":"Contributing to sustainable growth through efficient delivery, local value and long-term project performance."}}},"contactCta":{"eyebrow":"Start a Conversation","titleLine1":"Have a project","titleLine2":"in mind?","description":"Connect with FBS Contracting to discuss your project requirements and explore how we can work together.","primaryCta":"Contact Us"}},"innerPages":{"about":{"whoWeAre":{"eyebrow":"About Us","title":"Who We Are","introduction":"FBS Contracting Company is a leading construction company dedicated to delivering exceptional construction services. With a strong focus on quality, innovation, and client satisfaction, we have established ourselves as a trusted partner in the industry.","uniqueness":"At FBS Contracting, we understand that each project is unique, and we approach every endeavor with a commitment to excellence.","values":"Our core values of integrity, professionalism, and collaboration are at the heart of everything we do.","safety":"Safety is our top priority. We adhere to the highest industry standards and implement stringent safety protocols to ensure the well-being of our team members, clients, and the community.","expertise":"Whatever the project type, size, or location, we have the expertise, resources, and passion to bring your vision to life. Our team is committed to providing personalized service, working closely with you every step of the way to ensure your project’s success.","closing":"Thank you for considering FBS Contracting for your construction needs."},"chairmanSpeech":{"eyebrow":"About Us","title":"Chairman Speech","body":["Building on our accumulated experience and continuous ambition, FBS Contracting continues its journey toward strengthening its position as a trusted partner in the construction and contracting sector, delivering projects distinguished by quality, efficiency, and commitment.","We believe that our success is measured not only by the scale of the projects we deliver, but also by the quality of our work, the reliability of our commitments, and our ability to build long-term relationships and partnerships with our clients.","As the construction sector continues to evolve, we remain committed to strengthening our capabilities and expertise, investing in our people, and contributing to the Kingdom of Saudi Arabia’s ongoing journey of development and growth.","We move forward with confidence, guided by our commitment to quality, excellence, and safety, while continuing to pursue sustainable growth and further strengthen FBS Contracting’s position in the construction industry."],"name":"Faisal Bin Saedan","role":"Chairman"},"ceoSpeech":{"eyebrow":"About Us","title":"CEO Speech","body":["Praise be to Allah, Lord of the Worlds, and prayers and peace be upon the most honorable of the prophets and messengers, our Prophet Muhammad, and upon all his family and companions.","There is no doubt that the journey of a thousand miles begins with a single step, and to develop our present, we must set a clear vision for our future and continue to strive to improve our performance, find the best, and search for new opportunities to increase our activities within the Kingdom of Saudi Arabia in accordance with the Kingdom’s wise vision 2030.","Therefore, I pray to Allah Almighty that FBS Contracting Company will continue its journey and contribution to flourish our national economy and promote development for our children and society in order to achieve the vision.","In view of the giant construction boom that the Kingdom of Saudi Arabia is witnessing in the field of housing and the increasing demand in the construction market, the company has sought to provide everything that is finest and best in terms of speed and completion of projects, so this company was born.","To provide our esteemed customers with the best and highest quality, as well as accuracy in adhering to project delivery dates by providing a full team of engineers, consultants and contractors who have experience and high efficiency in this field, thus seeking to distinguish ourselves from other contracting companies and institutions by providing the best, and this is what our esteemed customers deserve."],"name":"Nawaf Binshuail","role":"CEO"},"ourTeam":{"eyebrow":"About Us","title":"Our Team","leadershipTitle":"Executive Leadership","managementTitle":"Company Management","members":[{"id":"nawaf","name":"Nawaf Binshuail","role":"CEO"},{"id":"wael","name":"Dr. Wael Darkazanli","role":"COO"},{"id":"ahmed","name":"Ahmed Talat","role":"CFO"},{"id":"mashael","name":"Mashael Alraqaib","role":"Business Developer Manager"},{"id":"nasser","name":"Nasser Yaseen","role":"Internal Audit"},{"id":"khaled","name":"Khaled Mansour","role":"Legal Affairs Advisor"}]},"whyFbs":{"eyebrow":"About Us","title":"Why FBS Contracting?","features":[{"title":"Experience and Expertise","description":"Our clients benefit from our extensive experience in the contracting industry as we have successfully completed numerous projects of varying complexities, demonstrating our ability to handle any challenge that may arise."},{"title":"Commitment to Quality","description":"We maintain rigorous quality control measures to ensure that our projects meet the highest standards. Our attention to detail and dedication to craftsmanship result in outstanding results that stand the test of time."},{"title":"Client-Centric Approach","description":"Our clients are at the forefront of everything we do where we believe in fostering strong and collaborative relationships built on trust and open communication."},{"title":"Safety First","description":"Our team undergoes regular safety training, ensuring a safe working environment for all through mitigating risks and creating a secure environment for everyone involved."},{"title":"Innovative Solutions","description":"We leverage cutting-edge technologies, sustainable practices, and modern construction methodologies to optimize project efficiency and minimize environmental impact which allows us to deliver cost-effective solutions without compromising quality."},{"title":"Strong Supplier and Partner Network","description":"Over the years, we have built robust relationships with trusted suppliers and industry partners. Our network of trusted suppliers and industry partners enables us to access high-quality materials, resources, and specialized expertise, enhancing the overall project delivery process."}]},"visionMission":{"eyebrow":"About Us","title":"Vision & Mission","vision":{"title":"Our Vision","description":"To be among the top leading construction companies as a brand recognized for quality and innovation, supporting our employees and the clients we work for, by being their first choice contractor."},"mission":{"title":"Our Mission","description":"Providing safe and sustainable projects and services that support our core values and achieve our clients’ goals."},"objectives":{"title":"Our Objectives","items":["Establish and maintain standard practice methods in the construction industry.","Maintaining a progressive and competitive construction industry.","Facilitating harmonious industry-consumer relations."]}},"saudiVision2030":{"eyebrow":"About Us","title":"Saudi Vision 2030","statement":"By committing to Vision 2030 principles, we aim to contribute to the successful implementation of Saudi Vision 2030 and play an active role in the sustainable development of Saudi Arabia.","description":"At FBS Contracting, we are committed to supporting and aligning with the goals and objectives of Saudi Vision 2030. We recognize the significance of this transformative vision in shaping the future of Saudi Arabia and the construction industry. As such, we pledge to contribute to the realization of Saudi Vision 2030 through the following commitments:","commitmentsTitle":"Our Commitments","commitments":["Supporting Economic Diversification","Promoting Local Employment and Skills Development","Embracing Innovation and Technology","Adopting Sustainable Practices"]},"coreValues":{"eyebrow":"About Us","title":"Our Core Values","values":["Community","Innovation","Excellence","Sustainability","Customer","Integrity"]}},"sustainability":{"environmental":{"eyebrow":"Sustainability","title":"Environmental Responsibility","introduction":"FBS Contracting is committed to protecting the environment through sustainable practices and the continual improvement of its Environmental Management System. Our environmental policy provides a framework for setting objectives, improving performance, and meeting applicable environmental requirements.","commitmentsTitle":"Our Environmental Commitments","commitments":[{"title":"Environmental Protection","description":"Minimizing environmental impact by preventing pollution, reducing waste, conserving resources, and protecting the natural environment."},{"title":"Compliance Obligations","description":"Meeting applicable environmental laws, regulations, and other relevant requirements to support responsible operations."},{"title":"Continual Improvement","description":"Improving environmental performance through objectives, regular audits, and corrective and preventive actions."},{"title":"Sustainable Resource Use","description":"Focusing on responsible resource use and energy efficiency, with the aim of reducing our carbon footprint."},{"title":"Biodiversity and Ecosystems Protection","description":"Considering the environmental impacts of our activities and taking measures to mitigate adverse effects on biodiversity and ecosystems."}],"closing":"Environmental stewardship and sustainable development are integral to our environmental policy."},"social":{"eyebrow":"Sustainability","title":"Social Responsibility","introduction":"At FBS Contracting, the well-being of people, workplace safety, employee development and strong stakeholder relationships are important aspects of our approach to responsible construction.","commitmentsTitle":"Our Social Priorities","commitments":[{"title":"Health and Safety","description":"We are committed to providing safe and healthy working conditions for employees, contractors and visitors through risk assessment, preventive measures and continual improvement."},{"title":"Local Employment and Skills","description":"As part of our commitment to Saudi Vision 2030, we support local employment and skills development."},{"title":"Employee Engagement","description":"We recognize the importance of competent, well-trained and engaged employees, and support their participation in improving our management systems."},{"title":"Stakeholder Relationships","description":"We aim to maintain collaborative relationships with customers, employees, suppliers and other stakeholders, while considering the well-being of the communities connected to our work."}],"closing":"Our approach places people, safety, skills development and responsible relationships at the center of long-term progress."},"economic":{"eyebrow":"Sustainability","title":"Economic Responsibility","introduction":"At FBS Contracting, our approach to economic responsibility is reflected in our commitment to supporting Saudi Vision 2030, delivering integrated construction services, managing resources efficiently, and building strong relationships with our partners.","commitmentsTitle":"Our Economic Priorities","commitments":[{"title":"Supporting Economic Diversification","description":"We are committed to supporting the economic diversification objectives of Saudi Vision 2030 and contributing to the Kingdom’s long-term development."},{"title":"Integrated Project Delivery","description":"Our comprehensive services cover different stages of the project lifecycle, supported by coordination across disciplines to improve the consistency of project planning and execution."},{"title":"Efficient Resource Management","description":"We adopt a process-based approach to managing activities and resources efficiently, with a focus on achieving effective and reliable project outcomes."},{"title":"Strong Supplier Relationships","description":"We seek to establish mutually beneficial relationships with suppliers and other stakeholders to strengthen cooperation and support the creation of long-term value."}],"closing":"Through integrated services, efficient operations, and responsible partnerships, we aim to support sustainable economic development."},"continuousImprovement":{"eyebrow":"Sustainability","title":"Continuous Improvement","introduction":"At FBS Contracting, continual improvement is an important part of our quality, occupational health and safety, and environmental management policies. We are committed to reviewing objectives, evaluating performance, conducting audits, and implementing measures that support better outcomes.","systemsTitle":"Our Management Commitments","systems":[{"title":"Quality Management","description":"We are committed to continually improving our Quality Management System through reviewing quality objectives, conducting internal audits, and taking corrective and preventive actions to enhance performance and customer satisfaction."},{"title":"Occupational Health & Safety","description":"We strive to improve occupational health and safety performance through risk reduction, reviewing safety objectives, internal audits, corrective actions, and worker consultation and participation."},{"title":"Environmental Management","description":"We seek to improve environmental performance through environmental objectives, regular audits, and corrective and preventive actions, while supporting sustainable practices and responsible resource use."}],"approachTitle":"Our Improvement Approach","steps":[{"title":"Set and Review Objectives","description":"Establish and regularly review objectives aligned with our management policies and organizational direction."},{"title":"Evaluate and Audit","description":"Assess performance, conduct internal audits, and use relevant information to identify improvement needs."},{"title":"Take Corrective Action","description":"Address nonconformities and implement corrective and preventive measures to strengthen management processes."},{"title":"Support Ongoing Development","description":"Use evidence-based decisions and employee participation to support improvements across our operations."}],"closing":"Continuous improvement supports our commitment to quality, workplace safety, environmental responsibility and long-term organizational performance."}},"businessContinuity":{"riskAssessment":{"eyebrow":"Business Continuity","title":"Risk Assessment and Management","introduction":"FBS Contracting is committed to maintaining a resilient and adaptive Business Continuity Management System. Our approach emphasizes identifying and mitigating potential risks, preparing for disruptions, and supporting the continued delivery of our products and services.","focusTitle":"Our Approach to Risk Management","focusAreas":[{"title":"Risk Identification and Mitigation","description":"Our Business Continuity Policy emphasizes identifying potential risks and taking measures to mitigate them as part of organizational preparedness."},{"title":"Preparedness and Response","description":"We are committed to strengthening resilience through preparing for, responding to, and recovering from disruptions."},{"title":"Compliance Obligations","description":"We commit to meeting applicable legal and other requirements related to business continuity to support responsible operations."},{"title":"Resource Availability","description":"Personnel, technology, infrastructure, and financial resources are important elements in supporting our business continuity strategies and solutions."}],"closing":"These principles support our commitment to business continuity, preparedness, and organizational resilience."},"businessImpactAnalysis":{"eyebrow":"Business Continuity","title":"Business Impact Analysis","introduction":"Business Impact Analysis is an important aspect of the preparedness and resilience principles outlined in FBS Contracting’s Business Continuity Policy. It supports understanding the potential effects of disruptions and informs the development of appropriate recovery strategies.","focusTitle":"Our Business Continuity Priorities","focusAreas":[{"title":"Understanding Disruption Impact","description":"Our Business Continuity Policy recognizes the importance of conducting business impact analyses as part of preparing for potential disruptions."},{"title":"Supporting Service Continuity","description":"Our commitment to business continuity focuses on supporting the continued delivery of products and services during and after disruptions."},{"title":"Considering Resource Requirements","description":"Personnel, technology, infrastructure, and financial resources are identified as important elements in supporting business continuity strategies and solutions."},{"title":"Informing Recovery Strategies","description":"Business impact analysis contributes to organizational preparedness alongside risk identification, mitigation, and the development of effective recovery strategies."}],"closing":"Understanding the impact of potential disruptions supports our commitment to resilience, preparedness, and effective business continuity planning."},"planDevelopment":{"eyebrow":"Business Continuity","title":"Plan Development","introduction":"At FBS Contracting, our Business Continuity Policy provides a framework for organizational preparedness, response, and recovery. It emphasizes identifying potential risks, understanding the impact of disruptions, developing effective recovery strategies, and ensuring the availability of essential resources.","focusTitle":"Our Business Continuity Planning Principles","focusAreas":[{"title":"Risk and Impact Considerations","description":"Identifying potential risks and conducting business impact analyses are important foundations for developing effective business continuity strategies."},{"title":"Response and Recovery Strategies","description":"Our Business Continuity Policy emphasizes preparing for, responding to, and recovering from disruptions through appropriate recovery strategies."},{"title":"Resource and Stakeholder Requirements","description":"Business continuity planning considers the availability of personnel, technology, infrastructure, and financial resources, alongside the needs of customers, employees, suppliers, and regulatory authorities."},{"title":"Review and Continual Improvement","description":"We are committed to reviewing business continuity objectives, conducting audits, and implementing corrective and preventive actions to support continual improvement."}],"closing":"These planning principles support our commitment to organizational resilience and the continued delivery of products and services during and after disruptions."},"recoveryRestoration":{"eyebrow":"Business Continuity","title":"Recovery and Restoration","introduction":"FBS Contracting is committed to strengthening its organizational resilience through preparedness, response, and recovery from disruptions. Our Business Continuity Policy emphasizes the development of effective recovery strategies and the availability of essential resources to support continued service delivery.","focusTitle":"Our Recovery and Restoration Principles","focusAreas":[{"title":"Preparedness and Response","description":"Our Business Continuity Policy emphasizes preparing for potential disruptions and responding to them as part of maintaining organizational resilience."},{"title":"Recovery Strategies","description":"We recognize the importance of developing effective recovery strategies informed by risk identification, mitigation, and business impact analysis."},{"title":"Availability of Essential Resources","description":"Personnel, technology, infrastructure, and financial resources are important elements in supporting business continuity and recovery solutions."},{"title":"Stakeholder Considerations","description":"Our approach considers the needs and expectations of customers, employees, suppliers, and regulatory authorities when supporting business continuity."}],"closing":"Through preparedness, effective recovery strategies, resource management, and continual improvement, we aim to strengthen resilience and support the continuity of our operations."},"leadershipAccountability":{"eyebrow":"Business Continuity","title":"Leadership and Accountability","introduction":"At FBS Contracting, our Business Continuity Policy supports our strategic direction and provides a framework for business continuity objectives, responsible operations, and continual improvement. Organizational resilience is supported through appropriate resource management, compliance commitments, and engagement with relevant stakeholders.","focusTitle":"Our Governance Commitments","focusAreas":[{"title":"Strategic Direction and Objectives","description":"Our Business Continuity Policy supports the organization’s strategic direction and provides a framework for establishing and reviewing business continuity objectives."},{"title":"Compliance and Responsible Operations","description":"We are committed to meeting applicable legal and other requirements related to business continuity to support responsible operations and regulatory compliance."},{"title":"Resource Management","description":"We recognize the importance of ensuring the availability of personnel, technology, infrastructure, and financial resources to support business continuity strategies and solutions."},{"title":"Stakeholder Engagement and Improvement","description":"We are committed to considering the needs and expectations of customers, employees, suppliers, and regulatory authorities, alongside reviewing objectives, conducting audits, and supporting continual improvement."}],"closing":"Through clear organizational commitments, responsible resource management, stakeholder engagement, and continual improvement, we aim to strengthen business continuity and resilience."}},"careers":{"eyebrow":"Careers & Training","title":"Careers","introduction":"At FBS Contracting, we recognize the importance of talented people in delivering quality construction services. We value professionalism, collaboration, and continuous development as we work toward building a stronger future.","opportunitiesTitle":"Career Opportunities","noVacanciesTitle":"Explore Opportunities With Us","noVacanciesDescription":"Current job openings will be displayed here when announced. You can also prepare a general application using the form below.","formTitle":"Career Application","formDescription":"Tell us about yourself and share your professional experience.","nameLabel":"Full Name","emailLabel":"Email Address","subjectLabel":"Subject","messageLabel":"Your Message","cvLabel":"Attach Your CV / Resume","submitLabel":"Review Application","demoNotice":"Demo form only. Applications are not submitted or stored at this stage.","cvHint":"PDF, DOC or DOCX — Maximum 5 MB","invalidCvType":"Please select a PDF, DOC or DOCX file.","invalidCvSize":"The file must not exceed 5 MB.","reviewTitle":"Review Your Application","closeLabel":"Close","notAttachedLabel":"Not attached"},"training":{"eyebrow":"Careers & Training","title":"Training","leadTitle":"Investing in People and Skills","introduction":"At FBS Contracting, developing people is an important part of our commitment to quality and continuous improvement. We recognize the value of competent, well-trained, and engaged employees, while supporting local skills development in line with Saudi Vision 2030.","visualEyebrow":"PEOPLE & DEVELOPMENT","visualTitle":"Building Skills for a Stronger Future","prioritiesTitle":"Our People Development Priorities","priorities":[{"title":"Local Skills Development","description":"As part of our commitment to Saudi Vision 2030, we support local employment and skills development to contribute to the Kingdom’s long-term progress."},{"title":"Employee Competence","description":"Our Quality Management Policy emphasizes the importance of competent, well-trained, and engaged employees in maintaining and improving our operations."},{"title":"Safety Participation","description":"Our Occupational Health and Safety Policy emphasizes worker consultation and participation in planning, evaluating, and improving workplace safety."}],"closing":"We believe that developing people, supporting competence, and encouraging active participation contribute to a stronger organization."},"supplierRegistration":{"eyebrow":"Business Partnerships","title":"Supplier Registration","introduction":"At FBS Contracting, we recognize the importance of strong and collaborative relationships with suppliers and business partners. We welcome opportunities to connect with companies offering products and services relevant to the construction industry.","formTitle":"Supplier Information","formDescription":"Share your company information and area of specialization using the form below.","companyNameLabel":"Company Name","contactNameLabel":"Contact Person","emailLabel":"Business Email","phoneLabel":"Phone Number","categoryLabel":"Business Category","categoryPlaceholder":"Select a Category","notesLabel":"Company Overview","profileLabel":"Attach Company Profile","profileHint":"PDF, DOC or DOCX — Maximum 5 MB","categories":[{"value":"materials","label":"Construction Materials"},{"value":"subcontracting","label":"Subcontracting"},{"value":"equipment","label":"Equipment & Machinery"},{"value":"services","label":"Professional Services"},{"value":"other","label":"Other"}],"submitLabel":"Review Registration","reviewTitle":"Review Supplier Information","closeLabel":"Close","notAttachedLabel":"Not attached","invalidPhone":"Enter 8–15 digits. Use only spaces, hyphens, parentheses and an optional leading +.","invalidFileType":"Please select a PDF, DOC or DOCX file.","invalidFileSize":"The file must not exceed 5 MB.","demoNotice":"Demo form only. Supplier information is not submitted or stored at this stage."},"contact":{"eyebrow":"Get in Touch","title":"Contact Us","introduction":"Have a question about our construction services or potential business opportunities? Get in touch with FBS Contracting. We welcome inquiries from clients, partners, and other interested parties.","detailsTitle":"Contact Information","phoneLabel":"Phone Number","emailLabel":"Email Address","addressLabel":"Our Location","address":"Al-Taawun District, Riyadh, Saudi Arabia","formTitle":"Send Us a Message","formDescription":"Share your inquiry using the form below.","nameLabel":"Full Name","subjectLabel":"Subject","messageLabel":"Your Message","reviewButton":"Review Message","reviewTitle":"Review Your Message","closeLabel":"Close","notProvidedLabel":"Not provided","requiredError":"Please complete all required fields.","demoNotice":"This is a demonstration form. Messages are not submitted or stored at this stage."}},"projectDetails":{"eyebrow":"Our Projects","informationTitle":"Project Information","locationLabel":"Location","categoryLabel":"Project Category","constructionPeriodLabel":"Construction Period","unitsLabel":"Number of Units","apartmentsLabel":"Apartments","villasLabel":"Villas","backToProjects":"Back to Projects","notFoundTitle":"Project Not Found","notFoundDescription":"The requested project could not be found."},"validation":{"requiredField":"This field is required.","invalidEmail":"Please enter a valid email address.","invalidCategory":"Please select a business category."},"notFound":{"title":"Page Not Found","description":"The page you are looking for could not be found.","backToHome":"Back to Home"},"footer":{"description":"Delivering residential and commercial developments across Saudi Arabia with quality, reliability and long-term value.","companyTitle":"Company","projectsTitle":"Projects","connectTitle":"Connect","whoWeAre":"Who We Are","visionMission":"Vision & Mission","values":"Our Values","residential":"Residential","commercial":"Commercial","sustainability":"Sustainability","careers":"Careers","suppliers":"Supplier Registration","contact":"Contact","copyright":"FBS Contracting. All rights reserved."},"language":{"english":"English","arabic":"العربية"}},"ar":{"loadingPage":"جارٍ تحميل الصفحة…","navigation":{"logo_t1":"FBS","logo_t2":"للمقاولات","home":"الرئيسية","aboutUs":"من نحن","whoWeAre":"من نحن","ceoMessage":"كلمة الرئيس التنفيذي","ourTeam":"فريقنا","whyFbsContracting":"لماذا FBS للمقاولات؟","visionMission":"الرؤية والرسالة","saudiVision2030":"رؤية السعودية 2030","coreValues":"قيمنا","ourProjects":"مشاريعنا","residential":"السكني","commercial":"التجاري","sustainability":"الاستدامة","environmentalResponsibility":"المسؤولية البيئية","socialResponsibility":"المسؤولية الاجتماعية","economicResponsibility":"المسؤولية الاقتصادية","continuousImprovement":"التحسين المستمر","businessContinuity":"استمرارية الأعمال","riskAssessmentManagement":"تقييم وإدارة المخاطر","businessImpactAnalysis":"تحليل تأثير الأعمال","planDevelopment":"تطوير الخطط","recoveryRestoration":"التعافي والاستعادة","leadershipAccountability":"القيادة والمسؤولية","careersTraining":"الوظائف والتدريب","careers":"الوظائف","training":"التدريب","supplierRegistration":"تسجيل الموردين","contact":"تواصل معنا","mainNavigationLabel":"التنقل الرئيسي","openMenuLabel":"فتح القائمة","menu":"القائمة","close":"إغلاق"},"home":{"hero":{"imageAlt":"عمارة مشروع جوهرة السحاب السكني في الرياض","statistics":{"heading":"FBS للمقاولات بالأرقام","approvalNotice":"أرقام توضيحية من التصميم الحالي للشركة، بانتظار الاعتماد الرسمي من العميل.","thousand":"ألف","billion":"مليار","currencyUnit":"ر.س","labels":{"projectValue":"قيمة المشاريع","residentialProjects":"مشاريع سكنية","residentialUnits":"وحدات سكنية","builtUpArea":"مساحة البناء","commercialProjects":"مشاريع تجارية","concreteWorks":"الأعمال الخرسانية","employees":"العاملون"}},"eyebrow":"FBS للمقاولات","titleLine1":"نبني برؤية","titleLine2":"تصنع المستقبل","description":"نقدم مشاريع سكنية وتجارية في المملكة العربية السعودية بجودة وموثوقية والتزام بقيمة طويلة الأمد.","primaryCta":"استكشف المشاريع","secondaryCta":"اكتشف FBS","location":"المملكة العربية السعودية"},"companyIntroduction":{"eyebrow":"من نحن","titleLine1":"رؤية تصنع","titleLine2":"واقعًا","description":"شركة FBS للمقاولات هي شركة إنشاءات رائدة متخصصة في تقديم خدمات بناء استثنائية. مع التركيز القوي على الجودة والابتكار ورضا العملاء، أثبتنا مكانتنا كشريك موثوق في قطاع المقاولات والتشييد.","secondaryText":"ندرك أن كل مشروع فريد من نوعه، ونعمل بالتزام بالتميز والسلامة والتعاون الوثيق مع عملائنا لتحقيق رؤيتهم على أرض الواقع.","cta":"تعرف على FBS للمقاولات"},"capabilities":{"eyebrow":"خدمات الشركة","titleLine1":"خدمات متكاملة","titleLine2":"من الفكرة إلى التنفيذ","description":"نقدم خدمات شاملة طوال دورة حياة المشروع، بدءًا من دراسة الجدوى الأولية وتصميم المفهوم وحتى أعمال البناء. ومن خلال شراكاتنا مع خبراء في مختلف التخصصات، نقدم نهجًا متكاملًا يضمن التنسيق والتنفيذ الفعال للمشاريع.","items":["دراسة الجدوى","تطوير الأراضي","إدارة التصميم","أعمال البناء","أعمال الصيانة"]},"projectCategories":{"eyebrow":"مشاريعنا","titleLine1":"مشاريعنا عبر","titleLine2":"قطاعين رئيسيين","description":"استكشف مشاريع FBS للمقاولات في القطاعين السكني والتجاري داخل المملكة العربية السعودية.","residential":{"title":"السكني","description":"مشاريع سكنية متكاملة تركز على الجودة والراحة والقيمة طويلة الأمد."},"commercial":{"title":"التجاري","description":"مشاريع تجارية يتم تنفيذها بكفاءة ودقة وفهم واضح لاحتياجات الأعمال."}},"projectMap":{"selectedProjectLabel":"المشروع المحدد","photoPinHint":"اختر صورة المشروع للاطلاع على تفاصيله.","photoPositionNote":"مواضع الصور وخطوط الربط توضيحية، وليست إحداثيات دقيقة للمشاريع.","projectSingular":"مشروع","projectPlural":"مشاريع","countryLabel":"المملكة العربية السعودية","eyebrow":"نطاق مشاريعنا","titleLine1":"نبني في مختلف","titleLine2":"مناطق المملكة","description":"استكشف مجموعة مختارة من مشاريع FBS للمقاولات في خمس مناطق بالمملكة العربية السعودية.","viewProject":"عرض المشروع","projects":{"riyadh":{"title":"جوهرة السحاب","type":"سكني","location":"الرياض"},"jeddah":{"title":"نزل خيالا","type":"سكني","location":"جدة"},"madinah":{"title":"نزل الدار","type":"سكني","location":"المدينة المنورة"},"taif":{"title":"ملفى الحوية","type":"سكني","location":"الطائف"},"tabuk":{"title":"ملفى تبوك هيلز","type":"سكني","location":"تبوك"}}},"vision2030":{"eyebrow":"رؤية السعودية 2030","titleLine1":"نساهم في بناء","titleLine2":"مملكة مزدهرة","description":"تساهم FBS للمقاولات في دعم تطلعات المملكة التنموية من خلال تنفيذ مشاريع تدعم النمو المستدام والمجتمعات القوية والقيمة طويلة الأمد.","cta":"اكتشف رؤية السعودية 2030"},"values":{"eyebrow":"قيمنا","titleLine1":"قيم تقود","titleLine2":"طريقة عملنا","description":"تعرّف على القيم الأساسية الست التي توجه أعمال شركة FBS للمقاولات.","items":{"integrity":{"title":"النزاهة","description":"نعمل بشفافية ومسؤولية واحترام في جميع علاقاتنا المهنية."},"quality":{"title":"الجودة","description":"نحافظ على معايير عالية في جميع مراحل تنفيذ المشروع."},"collaboration":{"title":"التعاون","description":"نوحد فرق العمل والتخصصات والشركاء لتحقيق أهداف المشروع المشتركة."},"responsibility":{"title":"المسؤولية","description":"نتعامل مع كل مشروع باهتمام بالإنسان والمجتمع والأثر طويل الأمد."}}},"sustainability":{"eyebrow":"الاستدامة","titleLine1":"نبني بمسؤولية","titleLine2":"تمتد للمستقبل","description":"يراعي نهجنا المسؤولية البيئية والاجتماعية والاقتصادية كجزء من تحقيق قيمة طويلة الأمد من خلال المشاريع التي ننفذها.","cta":"اكتشف الاستدامة","items":{"environmental":{"title":"المسؤولية البيئية","description":"دعم ممارسات أكثر مسؤولية في تنفيذ المشاريع مع الاهتمام بالموارد والكفاءة والأثر البيئي طويل الأمد."},"social":{"title":"المسؤولية الاجتماعية","description":"خلق قيمة للأفراد والمجتمعات من خلال التنفيذ المسؤول والتعاون الفعّال في المشاريع."},"economic":{"title":"المسؤولية الاقتصادية","description":"المساهمة في النمو المستدام من خلال كفاءة التنفيذ وتعزيز القيمة المحلية والأداء طويل الأمد."}}},"contactCta":{"eyebrow":"ابدأ التواصل معنا","titleLine1":"لديك مشروع","titleLine2":"تريد تنفيذه؟","description":"تواصل مع FBS للمقاولات لمناقشة متطلبات مشروعك والتعرف على فرص التعاون معنا.","primaryCta":"تواصل معنا"}},"innerPages":{"about":{"whoWeAre":{"eyebrow":"من نحن","title":"من نحن؟","introduction":"شركة FBS للمقاولات هي شركة إنشاءات رائدة متخصصة في تقديم خدمات بناء استثنائية. مع التركيز القوي على الجودة والابتكار ورضا العملاء، أنشأنا أنفسنا كشريك موثوق به في هذه الصناعة.","uniqueness":"في FBS للمقاولات، ندرك أن كل مشروع فريد من نوعه، ونتعامل مع كل مسعى مع الالتزام بالتميز.","values":"إن قيمنا الأساسية المتمثلة في النزاهة والكفاءة المهنية والتعاون هي جوهر كل ما نقوم به.","safety":"السلامة هي أولويتنا القصوى. نحن نلتزم بأعلى معايير الصناعة وننفذ بروتوكولات أمان صارمة لضمان رفاهية أعضاء فريقنا وعملائنا والمجتمع.","expertise":"مهما كان نوع المشروع أو حجمه أو موقعه، فلدينا الخبرة والموارد والشغف لتحقيق رؤيتك على أرض الواقع. يلتزم فريقنا بتقديم خدمة مخصصة، ويعمل معك بشكل وثيق في كل خطوة على الطريق لضمان نجاح مشروعك.","closing":"نشكرك على اهتمامك بشركة FBS للمقاولات لتلبية احتياجات البناء الخاصة بك."},"chairmanSpeech":{"eyebrow":"من نحن","title":"كلمة رئيس مجلس الإدارة","body":["انطلاقًا من خبراتنا المتراكمة وطموحنا المستمر، تواصل شركة FBS للمقاولات مسيرتها نحو تعزيز مكانتها كشريك موثوق في قطاع المقاولات والتشييد، من خلال تقديم مشاريع تتميز بالجودة والكفاءة والالتزام.","نؤمن بأن نجاحنا لا يقاس بحجم المشاريع التي ننفذها فحسب، بل بجودة أعمالنا، وموثوقية التزاماتنا، وقدرتنا على بناء علاقات وشراكات طويلة الأمد مع عملائنا.","ومع ما يشهده قطاع المقاولات من تطور متسارع، نواصل تعزيز قدراتنا وكفاءاتنا، والاستثمار في كوادرنا وخبراتنا، لنكون جزءًا فاعلًا في مسيرة التنمية والبناء في المملكة العربية السعودية.","ونمضي بثقة نحو المستقبل، ملتزمين بالجودة والتميز والسلامة، ومواصلين جهودنا لتحقيق نمو مستدام وتعزيز مكانة FBS للمقاولات في قطاع المقاولات."],"name":"فيصل بن سعيدان","role":"رئيس مجلس الإدارة"},"ceoSpeech":{"eyebrow":"من نحن","title":"كلمة الرئيس التنفيذي","body":["الحمد لله رب العالمين، والصلاة والسلام على أشرف الأنبياء والمرسلين، نبينا محمد وعلى آله وصحبه أجمعين.","مما لا شك فيه أن رحلة الألف ميل تبدأ بخطوة واحدة، ولتطوير حاضرنا، لا بد من وضع رؤية واضحة لمستقبلنا، ومواصلة السعي لتحسين أداء عملنا، والبحث عن الأفضل وفرص جديدة لزيادة أنشطتنا داخل المملكة العربية السعودية بما يتوافق مع رؤية المملكة الطموحة 2030.","لذا، أدعو الله عز وجل أن تواصل شركة إف بي إس (FBS) للمقاولات مسيرتها ومساهمتها في ازدهار اقتصادنا الوطني وتعزيز التنمية لأبنائنا ومجتمعنا تحليقاً نحو تحقيق الرؤية.","وفي ظل النهضة العمرانية العملاقة التي تشهدها المملكة العربية السعودية في مجال الإسكان والطلب المتزايد في سوق الإنشاءات، سعت الشركة إلى تقديم كل ما هو أفضل وأجود من حيث السرعة وإنجاز المشاريع، ومن هنا ولدت هذه الشركة.","لتقديم الأفضل وأعلى مستويات الجودة لعملائنا الكرام، فضلاً عن الدقة والالتزام بمواعيد تسليم المشاريع، وذلك من خلال توفير فريق كامل من المهندسين والاستشاريين والمقاولين ذوي الخبرة والكفاءة العالية في هذا المجال، سعياً منا للتميز عن باقي شركات ومؤسسات المقاولات الأخرى وتقديم الأفضل دائماً، وهو ما يستحقه عملاؤنا الكرام."],"name":"نواف بن شعيل","role":"الرئيس التنفيذي"},"whyFbs":{"eyebrow":"من نحن","title":"لماذا FBS للمقاولات؟","features":[{"title":"الخبرة والكفاءة","description":"يستفيد عملاؤنا من خبرتنا الواسعة في مجال المقاولات. لقد أنجزنا بنجاح العديد من المشاريع ذات التعقيدات المختلفة، مما يدل على قدرتنا على التعامل مع أي تحد قد ينشأ."},{"title":"الالتزام بالجودة","description":"نحن نحافظ على تدابير صارمة لمراقبة الجودة لضمان تلبية مشاريعنا أعلى المعايير. اهتمامنا بالتفاصيل والتفاني في الحرفية يؤدي إلى نتائج باهرة تصمد أمام اختبار الزمن."},{"title":"التركيز على العملاء","description":"عملاؤنا هم في طليعة كل ما نقوم به، حيث نؤمن بتعزيز العلاقات القوية والتعاونية المبنية على الثقة والتواصل المفتوح."},{"title":"السلامة أولًا","description":"يخضع فريقنا لتدريب منتظم على السلامة، مما يضمن بيئة عمل آمنة للجميع من خلال تخفيف المخاطر وخلق بيئة آمنة لجميع المعنيين."},{"title":"الحلول المبتكرة","description":"نستفيد من التقنيات المتطورة والممارسات المستدامة ومنهجيات البناء الحديثة لتعزيز كفاءة المشاريع وتقليل الأثر البيئي، مع تقديم حلول فعالة من حيث التكلفة دون المساس بالجودة."},{"title":"شبكة الموردين والشركاء القوية","description":"على مر السنين، بنينا علاقات قوية مع موردين موثوقين وشركاء في القطاع، مما يتيح لنا الوصول إلى مواد عالية الجودة وخبرات متخصصة وتعزيز كفاءة تنفيذ المشاريع."}]},"ourTeam":{"eyebrow":"من نحن","title":"فريق العمل","leadershipTitle":"القيادة التنفيذية","managementTitle":"إدارة الشركة","members":[{"id":"nawaf","name":"نواف بن شعيل","role":"الرئيس التنفيذي"},{"id":"wael","name":"د. وائل دركزنلي","role":"مدير العمليات"},{"id":"ahmed","name":"أحمد طلعت","role":"المدير المالي"},{"id":"mashael","name":"مشعل الرقيب","role":"مدير تطوير الأعمال"},{"id":"nasser","name":"ناصر ياسين","role":"مدير المراجعة الداخلية"},{"id":"khaled","name":"خالد منصور","role":"الشؤون القانونية"}]},"visionMission":{"eyebrow":"من نحن","title":"الرؤية والرسالة","vision":{"title":"رؤيتنا","description":"أن نكون من بين أفضل شركات البناء الرائدة كعلامة تجارية معروفة بالجودة والابتكار، ودعم موظفينا والعملاء الذين نعمل لديهم، من خلال كوننا الخيار الأول لهم."},"mission":{"title":"رسالتنا","description":"تقديم مشاريع وخدمات آمنة ومستدامة تدعم قيمنا الأساسية وتحقق أهداف عملائنا."},"objectives":{"title":"أهدافنا","items":["إنشاء والحفاظ على أساليب الممارسة القياسية في صناعة البناء والتشييد.","الحفاظ على صناعة البناء التقدمية والتنافسية.","تسهيل العلاقات المتناغمة بين الصناعة والمستهلك."]}},"saudiVision2030":{"eyebrow":"من نحن","title":"رؤية السعودية 2030","statement":"من خلال الالتزام بمبادئ رؤية 2030، نهدف إلى المساهمة في التنفيذ الناجح لرؤية السعودية 2030 ولعب دور فاعل في التنمية المستدامة في المملكة العربية السعودية.","description":"في FBS للمقاولات، نحن ملتزمون بدعم أهداف وغايات رؤية السعودية 2030 والمواءمة معها. ونحن ندرك أهمية هذه الرؤية التحويلية في تشكيل مستقبل المملكة العربية السعودية وصناعة البناء والتشييد. ومن هذا المنطلق، فإننا نتعهد بالمساهمة في تحقيق رؤية المملكة العربية السعودية 2030 من خلال الالتزامات التالية:","commitmentsTitle":"التزاماتنا","commitments":["دعم التنويع الاقتصادي","تعزيز العمالة المحلية وتنمية المهارات","احتضان الابتكار والتكنولوجيا","اعتماد الممارسات المستدامة"]},"coreValues":{"eyebrow":"من نحن","title":"قيمنا الأساسية","values":["المجتمع","الابتكار","التميز","الاستدامة","العميل","النزاهة"]}},"sustainability":{"environmental":{"eyebrow":"الاستدامة","title":"المسؤولية البيئية","introduction":"تلتزم شركة FBS للمقاولات بحماية البيئة من خلال الممارسات المستدامة والتحسين المستمر لنظام الإدارة البيئية. وتوفر سياستنا البيئية إطارًا لتحديد الأهداف وتحسين الأداء والالتزام بالمتطلبات البيئية المعمول بها.","commitmentsTitle":"التزاماتنا البيئية","commitments":[{"title":"حماية البيئة","description":"تقليل التأثير البيئي من خلال منع التلوث والحد من النفايات والحفاظ على الموارد وحماية البيئة الطبيعية."},{"title":"الالتزام بالمتطلبات البيئية","description":"الالتزام بالقوانين واللوائح والمتطلبات البيئية ذات الصلة لضمان تنفيذ العمليات بصورة مسؤولة."},{"title":"التحسين المستمر","description":"تحسين الأداء البيئي من خلال تحديد الأهداف وإجراء عمليات التدقيق المنتظمة وتنفيذ الإجراءات التصحيحية والوقائية."},{"title":"الاستخدام المستدام للموارد","description":"التركيز على الاستخدام المسؤول للموارد وكفاءة الطاقة بهدف تقليل البصمة الكربونية للشركة."},{"title":"حماية التنوع البيولوجي والنظم البيئية","description":"مراعاة التأثيرات البيئية للأنشطة واتخاذ التدابير اللازمة للتخفيف من الآثار السلبية على التنوع البيولوجي والنظم البيئية."}],"closing":"تُعد حماية البيئة والتنمية المستدامة جزءًا أساسيًا من التزام الشركة بسياستها البيئية."},"social":{"eyebrow":"الاستدامة","title":"المسؤولية الاجتماعية","introduction":"تولي شركة FBS للمقاولات أهمية لسلامة الأفراد ورفاهيتهم، وتطوير مهارات الموظفين، وبناء علاقات قوية مع الأطراف المعنية، ضمن نهجها المسؤول في قطاع البناء والتشييد.","commitmentsTitle":"أولوياتنا الاجتماعية","commitments":[{"title":"الصحة والسلامة المهنية","description":"نلتزم بتوفير ظروف عمل آمنة وصحية للموظفين والمقاولين والزوار من خلال تقييم المخاطر والإجراءات الوقائية والتحسين المستمر."},{"title":"التوظيف المحلي وتنمية المهارات","description":"في إطار التزامنا برؤية السعودية 2030، ندعم تعزيز فرص التوظيف المحلي وتنمية المهارات."},{"title":"مشاركة الموظفين","description":"نؤمن بأهمية الموظفين المؤهلين والمدربين والمشاركين بفاعلية في تطوير وتحسين أنظمة الإدارة بالشركة."},{"title":"العلاقات مع الأطراف المعنية","description":"نسعى إلى الحفاظ على علاقات تعاونية مع العملاء والموظفين والموردين ومختلف الأطراف المعنية، مع مراعاة رفاهية المجتمعات المرتبطة بأعمالنا."}],"closing":"يرتكز نهجنا على الاهتمام بالإنسان والسلامة وتنمية المهارات والعلاقات المسؤولة لدعم التقدم على المدى الطويل."},"economic":{"eyebrow":"الاستدامة","title":"المسؤولية الاقتصادية","introduction":"تنعكس مسؤوليتنا الاقتصادية في شركة FBS للمقاولات من خلال التزامنا بدعم رؤية السعودية 2030، وتقديم خدمات إنشائية متكاملة، وإدارة الموارد بكفاءة، وبناء علاقات قوية مع شركائنا.","commitmentsTitle":"أولوياتنا الاقتصادية","commitments":[{"title":"دعم التنويع الاقتصادي","description":"نلتزم بدعم أهداف التنويع الاقتصادي لرؤية السعودية 2030 والمساهمة في التنمية طويلة الأمد بالمملكة."},{"title":"التنفيذ المتكامل للمشاريع","description":"نقدم خدمات شاملة تغطي المراحل المختلفة لدورة حياة المشروع، مع التنسيق بين التخصصات المختلفة لتعزيز تكامل التخطيط والتنفيذ."},{"title":"الإدارة الفعالة للموارد","description":"نعتمد نهجًا منظمًا لإدارة الأنشطة والموارد بكفاءة، مع التركيز على تحقيق نتائج فعالة وموثوقة في تنفيذ المشاريع."},{"title":"العلاقات القوية مع الموردين","description":"نسعى إلى بناء علاقات متبادلة المنفعة مع الموردين والأطراف المعنية لتعزيز التعاون ودعم تحقيق قيمة طويلة الأمد."}],"closing":"من خلال الخدمات المتكاملة وكفاءة العمليات والشراكات المسؤولة، نسعى إلى دعم التنمية الاقتصادية المستدامة."},"continuousImprovement":{"eyebrow":"الاستدامة","title":"التحسين المستمر","introduction":"يمثل التحسين المستمر جزءًا مهمًا من سياسات شركة FBS للمقاولات في إدارة الجودة والصحة والسلامة المهنية والإدارة البيئية. ونلتزم بمراجعة الأهداف وتقييم الأداء وإجراء عمليات التدقيق وتنفيذ الإجراءات التي تدعم تحسين نتائج العمل.","systemsTitle":"التزاماتنا الإدارية","systems":[{"title":"إدارة الجودة","description":"نلتزم بالتحسين المستمر لنظام إدارة الجودة من خلال مراجعة أهداف الجودة وإجراء التدقيق الداخلي وتنفيذ الإجراءات التصحيحية والوقائية لتعزيز الأداء ورضا العملاء."},{"title":"الصحة والسلامة المهنية","description":"نسعى إلى تحسين أداء الصحة والسلامة المهنية من خلال الحد من المخاطر ومراجعة أهداف السلامة والتدقيق الداخلي والإجراءات التصحيحية ومشاركة العاملين والتشاور معهم."},{"title":"الإدارة البيئية","description":"نسعى إلى تحسين الأداء البيئي من خلال تحديد الأهداف البيئية وإجراء عمليات التدقيق المنتظمة وتنفيذ الإجراءات التصحيحية والوقائية ودعم الممارسات المستدامة والاستخدام المسؤول للموارد."}],"approachTitle":"منهجنا في التحسين المستمر","steps":[{"title":"تحديد الأهداف ومراجعتها","description":"تحديد الأهداف ومراجعتها بصورة منتظمة بما يتوافق مع سياسات الإدارة والتوجه العام للشركة."},{"title":"التقييم والتدقيق","description":"تقييم الأداء وإجراء عمليات التدقيق الداخلي والاستفادة من المعلومات المتاحة لتحديد فرص التحسين."},{"title":"اتخاذ الإجراءات التصحيحية","description":"معالجة حالات عدم المطابقة وتنفيذ الإجراءات التصحيحية والوقائية لتعزيز كفاءة العمليات الإدارية."},{"title":"دعم التطوير المستمر","description":"الاستفادة من القرارات المبنية على الأدلة ومشاركة الموظفين لدعم تحسين العمليات المختلفة."}],"closing":"يدعم التحسين المستمر التزامنا بالجودة وسلامة بيئة العمل والمسؤولية البيئية وتطوير الأداء المؤسسي على المدى الطويل."}},"businessContinuity":{"riskAssessment":{"eyebrow":"استمرارية الأعمال","title":"تقييم المخاطر وإدارتها","introduction":"تلتزم شركة FBS للمقاولات بالحفاظ على نظام مرن وقابل للتكيف لإدارة استمرارية الأعمال. ويركز نهجنا على تحديد المخاطر المحتملة والحد منها، والاستعداد للاضطرابات، ودعم استمرار تقديم المنتجات والخدمات.","focusTitle":"نهجنا في إدارة المخاطر","focusAreas":[{"title":"تحديد المخاطر والحد منها","description":"تركز سياسة استمرارية الأعمال على تحديد المخاطر المحتملة واتخاذ التدابير اللازمة للحد منها كجزء من الاستعداد المؤسسي."},{"title":"الاستعداد والاستجابة","description":"نلتزم بتعزيز مرونة الأعمال من خلال الاستعداد للاضطرابات والاستجابة لها والتعافي من آثارها."},{"title":"الالتزام بالمتطلبات التنظيمية","description":"نلتزم بالمتطلبات القانونية والتنظيمية وغيرها من المتطلبات المرتبطة باستمرارية الأعمال لدعم تنفيذ العمليات بصورة مسؤولة."},{"title":"توافر الموارد","description":"تمثل الموارد البشرية والتكنولوجيا والبنية التحتية والموارد المالية عناصر مهمة لدعم استراتيجيات وحلول استمرارية الأعمال."}],"closing":"تدعم هذه المبادئ التزامنا باستمرارية الأعمال والاستعداد والمرونة المؤسسية."},"businessImpactAnalysis":{"eyebrow":"استمرارية الأعمال","title":"تحليل أثر تعطل الأعمال","introduction":"يمثل تحليل أثر تعطل الأعمال جانبًا مهمًا من مبادئ الاستعداد والمرونة الواردة في سياسة استمرارية الأعمال لدى شركة FBS للمقاولات. ويساعد على فهم الآثار المحتملة للاضطرابات ودعم تطوير استراتيجيات التعافي المناسبة.","focusTitle":"أولوياتنا في استمرارية الأعمال","focusAreas":[{"title":"فهم تأثير الاضطرابات","description":"تؤكد سياسة استمرارية الأعمال أهمية إجراء تحليلات أثر تعطل الأعمال كجزء من الاستعداد للاضطرابات المحتملة."},{"title":"دعم استمرارية الخدمات","description":"يركز التزامنا باستمرارية الأعمال على دعم مواصلة تقديم المنتجات والخدمات أثناء الاضطرابات وبعدها."},{"title":"مراعاة متطلبات الموارد","description":"تُعد الموارد البشرية والتكنولوجيا والبنية التحتية والموارد المالية عناصر مهمة في دعم استراتيجيات وحلول استمرارية الأعمال."},{"title":"دعم استراتيجيات التعافي","description":"يساهم تحليل أثر تعطل الأعمال في دعم الاستعداد المؤسسي إلى جانب تحديد المخاطر والحد منها وتطوير استراتيجيات تعافٍ فعالة."}],"closing":"يساهم فهم الآثار المحتملة للاضطرابات في دعم التزامنا بالمرونة والاستعداد والتخطيط الفعال لاستمرارية الأعمال."},"planDevelopment":{"eyebrow":"استمرارية الأعمال","title":"تطوير الخطط","introduction":"توفر سياسة استمرارية الأعمال في شركة FBS للمقاولات إطارًا يدعم الاستعداد المؤسسي والاستجابة للاضطرابات والتعافي منها. وتركز على تحديد المخاطر المحتملة وفهم آثار تعطل الأعمال وتطوير استراتيجيات تعافٍ فعالة وضمان توافر الموارد الأساسية.","focusTitle":"مبادئ التخطيط لاستمرارية الأعمال","focusAreas":[{"title":"دراسة المخاطر وتأثيراتها","description":"يمثل تحديد المخاطر المحتملة وإجراء تحليلات أثر تعطل الأعمال أساسًا مهمًا لتطوير استراتيجيات فعالة لاستمرارية الأعمال."},{"title":"استراتيجيات الاستجابة والتعافي","description":"تؤكد سياسة استمرارية الأعمال أهمية الاستعداد للاضطرابات والاستجابة لها والتعافي منها من خلال استراتيجيات مناسبة."},{"title":"متطلبات الموارد والأطراف المعنية","description":"تراعي مبادئ التخطيط توافر الموارد البشرية والتكنولوجيا والبنية التحتية والموارد المالية، إلى جانب احتياجات العملاء والموظفين والموردين والجهات التنظيمية."},{"title":"المراجعة والتحسين المستمر","description":"نلتزم بمراجعة أهداف استمرارية الأعمال وإجراء عمليات التدقيق وتنفيذ الإجراءات التصحيحية والوقائية لدعم التحسين المستمر."}],"closing":"تدعم مبادئ التخطيط هذه التزامنا بالمرونة المؤسسية واستمرار تقديم المنتجات والخدمات أثناء الاضطرابات وبعدها."},"recoveryRestoration":{"eyebrow":"استمرارية الأعمال","title":"التعافي واستعادة الأعمال","introduction":"تلتزم شركة FBS للمقاولات بتعزيز مرونتها المؤسسية من خلال الاستعداد للاضطرابات والاستجابة لها والتعافي من آثارها. وتؤكد سياسة استمرارية الأعمال أهمية تطوير استراتيجيات تعافٍ فعالة وضمان توافر الموارد الأساسية لدعم استمرار تقديم الخدمات.","focusTitle":"مبادئ التعافي واستعادة الأعمال","focusAreas":[{"title":"الاستعداد والاستجابة","description":"تركز سياسة استمرارية الأعمال على الاستعداد للاضطرابات المحتملة والاستجابة لها باعتبار ذلك جزءًا من الحفاظ على المرونة المؤسسية."},{"title":"استراتيجيات التعافي","description":"نؤكد أهمية تطوير استراتيجيات تعافٍ فعالة تستند إلى تحديد المخاطر والحد منها وتحليل آثار تعطل الأعمال."},{"title":"توافر الموارد الأساسية","description":"تمثل الموارد البشرية والتكنولوجيا والبنية التحتية والموارد المالية عناصر مهمة لدعم استمرارية الأعمال وحلول التعافي."},{"title":"مراعاة الأطراف المعنية","description":"يراعي نهجنا احتياجات وتوقعات العملاء والموظفين والموردين والجهات التنظيمية عند دعم استمرارية الأعمال."}],"closing":"من خلال الاستعداد واستراتيجيات التعافي الفعالة وإدارة الموارد والتحسين المستمر، نسعى إلى تعزيز المرونة المؤسسية ودعم استمرارية عملياتنا."},"leadershipAccountability":{"eyebrow":"استمرارية الأعمال","title":"القيادة والمساءلة","introduction":"تدعم سياسة استمرارية الأعمال في شركة FBS للمقاولات التوجه الاستراتيجي للشركة، وتوفر إطارًا لتحديد أهداف استمرارية الأعمال وتعزيز العمليات المسؤولة والتحسين المستمر. كما تستند المرونة المؤسسية إلى الإدارة المناسبة للموارد والالتزام بالمتطلبات التنظيمية والتفاعل مع الأطراف المعنية.","focusTitle":"التزاماتنا في الحوكمة","focusAreas":[{"title":"التوجه الاستراتيجي والأهداف","description":"تدعم سياسة استمرارية الأعمال التوجه الاستراتيجي للشركة، وتوفر إطارًا لتحديد أهداف استمرارية الأعمال ومراجعتها."},{"title":"الالتزام والعمليات المسؤولة","description":"نلتزم بالمتطلبات القانونية والتنظيمية وغيرها من المتطلبات المتعلقة باستمرارية الأعمال، بما يدعم تنفيذ العمليات بصورة مسؤولة."},{"title":"إدارة الموارد","description":"نؤكد أهمية ضمان توافر الموارد البشرية والتكنولوجيا والبنية التحتية والموارد المالية اللازمة لدعم استراتيجيات وحلول استمرارية الأعمال."},{"title":"التفاعل مع الأطراف المعنية والتحسين","description":"نلتزم بمراعاة احتياجات وتوقعات العملاء والموظفين والموردين والجهات التنظيمية، إلى جانب مراجعة الأهداف وإجراء عمليات التدقيق ودعم التحسين المستمر."}],"closing":"من خلال الالتزامات المؤسسية الواضحة والإدارة المسؤولة للموارد والتفاعل مع الأطراف المعنية والتحسين المستمر، نسعى إلى تعزيز استمرارية الأعمال والمرونة المؤسسية."}},"careers":{"eyebrow":"الوظائف والتدريب","title":"الوظائف","introduction":"في شركة FBS للمقاولات، ندرك أهمية الكفاءات البشرية في تقديم خدمات إنشائية عالية الجودة. ونؤمن بقيم الاحترافية والتعاون والتطوير المستمر، ونسعى إلى بناء مستقبل أقوى من خلال كوادر مؤهلة وطموحة.","opportunitiesTitle":"الفرص الوظيفية","noVacanciesTitle":"اكتشف الفرص المهنية معنا","noVacanciesDescription":"سيتم عرض الوظائف المتاحة هنا عند الإعلان عنها. ويمكنك أيضًا تجهيز طلب تقديم عام من خلال النموذج التالي.","formTitle":"نموذج التقديم على وظيفة","formDescription":"عرّفنا بنفسك وشاركنا خبراتك ومؤهلاتك المهنية.","nameLabel":"الاسم بالكامل","emailLabel":"البريد الإلكتروني","subjectLabel":"الموضوع","messageLabel":"رسالتك","cvLabel":"إرفاق السيرة الذاتية","submitLabel":"مراجعة الطلب","demoNotice":"هذا نموذج تجريبي فقط، ولا يتم إرسال الطلبات أو تخزينها في المرحلة الحالية.","cvHint":"ملف PDF أو DOC أو DOCX — بحد أقصى 5 ميجابايت","invalidCvType":"يرجى اختيار ملف PDF أو DOC أو DOCX.","invalidCvSize":"يجب ألا يتجاوز حجم الملف 5 ميجابايت.","reviewTitle":"مراجعة طلب التقديم","closeLabel":"إغلاق","notAttachedLabel":"لم يتم إرفاق ملف"},"training":{"eyebrow":"الوظائف والتدريب","title":"التدريب","leadTitle":"الاستثمار في الإنسان وتنمية المهارات","introduction":"في شركة FBS للمقاولات، يمثل تطوير الكوادر البشرية جزءًا مهمًا من التزامنا بالجودة والتحسين المستمر. ونؤمن بأهمية الموظفين المؤهلين والمدربين والمشاركين بفاعلية في العمل، مع دعم تنمية المهارات المحلية بما يتماشى مع رؤية السعودية 2030.","visualEyebrow":"الكوادر البشرية والتطوير","visualTitle":"نبني المهارات لمستقبل أقوى","prioritiesTitle":"أولوياتنا في تطوير الكوادر البشرية","priorities":[{"title":"تنمية المهارات المحلية","description":"في إطار التزامنا برؤية السعودية 2030، ندعم التوظيف المحلي وتنمية المهارات للمساهمة في التنمية طويلة الأمد بالمملكة."},{"title":"تأهيل الموظفين","description":"تؤكد سياسة إدارة الجودة لدينا أهمية وجود موظفين مؤهلين ومدربين ومشاركين بفاعلية في الحفاظ على العمليات وتحسينها."},{"title":"المشاركة في السلامة المهنية","description":"تؤكد سياسة الصحة والسلامة المهنية أهمية التشاور مع العاملين ومشاركتهم في تخطيط وتقييم وتحسين بيئة العمل والسلامة المهنية."}],"closing":"نؤمن بأن تطوير الكوادر البشرية وتعزيز الكفاءة وتشجيع المشاركة الفعالة يساهم في بناء مؤسسة أكثر قوة واستدامة."},"supplierRegistration":{"eyebrow":"شراكات الأعمال","title":"تسجيل الموردين","introduction":"تؤمن شركة FBS للمقاولات بأهمية بناء علاقات قوية وتعاونية مع الموردين وشركاء الأعمال. ونرحب بالتواصل مع الشركات التي تقدم المنتجات والخدمات المرتبطة بقطاع البناء والتشييد.","formTitle":"بيانات المورد","formDescription":"شاركنا معلومات شركتك ومجال تخصصها من خلال النموذج التالي.","companyNameLabel":"اسم الشركة","contactNameLabel":"اسم مسؤول التواصل","emailLabel":"البريد الإلكتروني للشركة","phoneLabel":"رقم الهاتف","categoryLabel":"مجال النشاط","categoryPlaceholder":"اختر مجال النشاط","notesLabel":"نبذة عن الشركة","profileLabel":"إرفاق الملف التعريفي للشركة","profileHint":"ملف PDF أو DOC أو DOCX — بحد أقصى 5 ميجابايت","categories":[{"value":"materials","label":"مواد البناء"},{"value":"subcontracting","label":"مقاولات الباطن"},{"value":"equipment","label":"المعدات والآلات"},{"value":"services","label":"الخدمات المهنية"},{"value":"other","label":"أخرى"}],"submitLabel":"مراجعة بيانات التسجيل","reviewTitle":"مراجعة بيانات المورد","closeLabel":"إغلاق","notAttachedLabel":"لم يتم إرفاق ملف","invalidPhone":"أدخل من 8 إلى 15 رقمًا. يُسمح بالمسافات والشرطات والأقواس وعلامة + واحدة في البداية.","invalidFileType":"يرجى اختيار ملف PDF أو DOC أو DOCX.","invalidFileSize":"يجب ألا يتجاوز حجم الملف 5 ميجابايت.","demoNotice":"هذا نموذج تجريبي فقط، ولا يتم إرسال بيانات الموردين أو تخزينها في المرحلة الحالية."},"contact":{"eyebrow":"تواصل معنا","title":"اتصل بنا","introduction":"هل لديك استفسار حول خدماتنا الإنشائية أو فرص التعاون والشراكات؟ يسعد شركة FBS للمقاولات استقبال استفسارات العملاء والشركاء والجهات المهتمة بخدماتنا.","detailsTitle":"معلومات التواصل","phoneLabel":"رقم الهاتف","emailLabel":"البريد الإلكتروني","addressLabel":"موقعنا","address":"حي التعاون، الرياض، المملكة العربية السعودية","formTitle":"أرسل لنا رسالة","formDescription":"شاركنا استفسارك من خلال النموذج التالي.","nameLabel":"الاسم بالكامل","subjectLabel":"الموضوع","messageLabel":"رسالتك","reviewButton":"مراجعة الرسالة","reviewTitle":"مراجعة بيانات الرسالة","closeLabel":"إغلاق","notProvidedLabel":"غير مذكور","requiredError":"يرجى استكمال جميع الحقول المطلوبة.","demoNotice":"هذا نموذج تجريبي فقط، ولا يتم إرسال الرسائل أو تخزينها في المرحلة الحالية."}},"projectDetails":{"eyebrow":"مشاريعنا","informationTitle":"معلومات المشروع","locationLabel":"الموقع","categoryLabel":"تصنيف المشروع","constructionPeriodLabel":"فترة البناء","unitsLabel":"عدد الوحدات","apartmentsLabel":"شقة","villasLabel":"فيلا","backToProjects":"العودة إلى المشاريع","notFoundTitle":"المشروع غير موجود","notFoundDescription":"لم نتمكن من العثور على المشروع المطلوب."},"validation":{"requiredField":"هذا الحقل مطلوب.","invalidEmail":"يرجى إدخال بريد إلكتروني صحيح.","invalidCategory":"يرجى اختيار مجال النشاط."},"notFound":{"title":"الصفحة غير موجودة","description":"لم نتمكن من العثور على الصفحة التي تبحث عنها.","backToHome":"العودة إلى الصفحة الرئيسية"},"footer":{"description":"نقدم مشاريع سكنية وتجارية في المملكة العربية السعودية مع التركيز على الجودة والموثوقية والقيمة طويلة الأمد.","companyTitle":"الشركة","projectsTitle":"المشاريع","connectTitle":"تواصل معنا","whoWeAre":"من نحن","visionMission":"الرؤية والرسالة","values":"قيمنا","residential":"السكني","commercial":"التجاري","sustainability":"الاستدامة","careers":"الوظائف","suppliers":"تسجيل الموردين","contact":"تواصل معنا","copyright":"FBS للمقاولات. جميع الحقوق محفوظة."},"language":{"english":"English","arabic":"العربية"}}}',null,'corporate-v2:site_settings:corporate-settings','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = 'e0bde541-7b08-5e1e-a909-c767fb484c5b') on conflict do nothing;
