insert into public.content_translations (content_id,language_code,title,content) select '3b5f183d-2a0a-5335-a21f-b5e8044cba54','en','Home','{"hero":{"imageAlt":"Jawhart Al-Sahab residential architecture in Riyadh","statistics":{"heading":"FBS Contracting in numbers","approvalNotice":"Demo figures from the existing company artwork. Pending official client approval.","thousand":"K","billion":"B","currencyUnit":"SAR","labels":{"projectValue":"Project value","residentialProjects":"Residential projects","residentialUnits":"Residential units","builtUpArea":"Built-up area","commercialProjects":"Commercial projects","concreteWorks":"Concrete works","employees":"Employees"}},"eyebrow":"FBS Contracting","titleLine1":"Building with","titleLine2":"purpose.","description":"Delivering residential and commercial developments across Saudi Arabia through quality, reliability and a commitment to long-term value.","primaryCta":"Explore Projects","secondaryCta":"Discover FBS","location":"Kingdom of Saudi Arabia"},"companyIntroduction":{"eyebrow":"Who We Are","titleLine1":"A Vision That","titleLine2":"Shapes Reality.","description":"FBS Contracting Company is a leading construction company dedicated to delivering exceptional construction services. With a strong focus on quality, innovation, and client satisfaction, we have established ourselves as a trusted partner in the industry.","secondaryText":"We understand that every project is unique. Our commitment to excellence, safety, and close collaboration with clients guides us in bringing their visions to life.","cta":"Learn More About FBS"},"capabilities":{"eyebrow":"Company Services","titleLine1":"From concept","titleLine2":"to completion.","description":"We provide comprehensive services throughout the project lifecycle, from initial feasibility studies and concept design to construction works. Through partnerships with experts across disciplines, we offer an integrated approach to project planning and execution.","items":["Feasibility Study","Land Development","Design Management","Construction Works","Maintenance & Operations"]},"projectCategories":{"eyebrow":"Our Projects","titleLine1":"Built across two","titleLine2":"core sectors.","description":"Explore FBS Contracting projects across residential and commercial developments throughout Saudi Arabia.","residential":{"title":"Residential","description":"Integrated residential developments designed around quality, comfort and long-term value."},"commercial":{"title":"Commercial","description":"Commercial environments delivered with efficiency, precision and a clear understanding of business needs."}},"projectMap":{"selectedProjectLabel":"Selected Project","photoPinHint":"Select a project photo to explore its details.","photoPositionNote":"Photo positions and connectors are illustrative, not exact project coordinates.","projectSingular":"Project","projectPlural":"Projects","countryLabel":"Saudi Arabia","eyebrow":"Project Footprint","titleLine1":"Building across","titleLine2":"Saudi Arabia.","description":"Explore selected FBS Contracting projects across five regions of Saudi Arabia.","viewProject":"View Project","projects":{"riyadh":{"title":"Jawhart Al-Sahab","type":"Residential","location":"Riyadh"},"jeddah":{"title":"Nozol Khayala","type":"Residential","location":"Jeddah"},"madinah":{"title":"Nozol Al-Dar","type":"Residential","location":"Al Madinah Al Munawwarah"},"taif":{"title":"Malfa Al-Hawya","type":"Residential","location":"Taif"},"tabuk":{"title":"Malfa Tabuk Hills","type":"Residential","location":"Tabuk"}}},"vision2030":{"eyebrow":"Saudi Vision 2030","titleLine1":"Contributing to a","titleLine2":"growing Kingdom.","description":"FBS Contracting supports the Kingdom’s development ambitions by delivering projects that contribute to sustainable growth, stronger communities and long-term value.","cta":"Explore Saudi Vision 2030"},"values":{"eyebrow":"Our Values","titleLine1":"Values that guide","titleLine2":"how we build.","description":"Discover the six core values that guide FBS Contracting.","items":{"integrity":{"title":"Integrity","description":"We work with transparency, accountability and respect in every relationship."},"quality":{"title":"Quality","description":"We maintain a consistent focus on high standards across every stage of delivery."},"collaboration":{"title":"Collaboration","description":"We bring teams, disciplines and partners together around shared project goals."},"responsibility":{"title":"Responsibility","description":"We approach every project with care for people, communities and long-term impact."}}},"sustainability":{"eyebrow":"Sustainability","titleLine1":"Building with","titleLine2":"lasting responsibility.","description":"Our approach considers environmental, social and economic responsibility as part of creating long-term value through the projects we deliver.","cta":"Explore Sustainability","items":{"environmental":{"title":"Environmental Responsibility","description":"Supporting more responsible project practices with attention to resources, efficiency and long-term environmental impact."},"social":{"title":"Social Responsibility","description":"Creating value for people and communities through responsible delivery and collaborative project practices."},"economic":{"title":"Economic Responsibility","description":"Contributing to sustainable growth through efficient delivery, local value and long-term project performance."}}},"contactCta":{"eyebrow":"Start a Conversation","titleLine1":"Have a project","titleLine2":"in mind?","description":"Connect with FBS Contracting to discuss your project requirements and explore how we can work together.","primaryCta":"Contact Us"}}' where not exists (select 1 from public.content_translations where content_id = '3b5f183d-2a0a-5335-a21f-b5e8044cba54' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '3b5f183d-2a0a-5335-a21f-b5e8044cba54','ar','الرئيسية','{"hero":{"imageAlt":"عمارة مشروع جوهرة السحاب السكني في الرياض","statistics":{"heading":"FBS للمقاولات بالأرقام","approvalNotice":"أرقام توضيحية من التصميم الحالي للشركة، بانتظار الاعتماد الرسمي من العميل.","thousand":"ألف","billion":"مليار","currencyUnit":"ر.س","labels":{"projectValue":"قيمة المشاريع","residentialProjects":"مشاريع سكنية","residentialUnits":"وحدات سكنية","builtUpArea":"مساحة البناء","commercialProjects":"مشاريع تجارية","concreteWorks":"الأعمال الخرسانية","employees":"العاملون"}},"eyebrow":"FBS للمقاولات","titleLine1":"نبني برؤية","titleLine2":"تصنع المستقبل","description":"نقدم مشاريع سكنية وتجارية في المملكة العربية السعودية بجودة وموثوقية والتزام بقيمة طويلة الأمد.","primaryCta":"استكشف المشاريع","secondaryCta":"اكتشف FBS","location":"المملكة العربية السعودية"},"companyIntroduction":{"eyebrow":"من نحن","titleLine1":"رؤية تصنع","titleLine2":"واقعًا","description":"شركة FBS للمقاولات هي شركة إنشاءات رائدة متخصصة في تقديم خدمات بناء استثنائية. مع التركيز القوي على الجودة والابتكار ورضا العملاء، أثبتنا مكانتنا كشريك موثوق في قطاع المقاولات والتشييد.","secondaryText":"ندرك أن كل مشروع فريد من نوعه، ونعمل بالتزام بالتميز والسلامة والتعاون الوثيق مع عملائنا لتحقيق رؤيتهم على أرض الواقع.","cta":"تعرف على FBS للمقاولات"},"capabilities":{"eyebrow":"خدمات الشركة","titleLine1":"خدمات متكاملة","titleLine2":"من الفكرة إلى التنفيذ","description":"نقدم خدمات شاملة طوال دورة حياة المشروع، بدءًا من دراسة الجدوى الأولية وتصميم المفهوم وحتى أعمال البناء. ومن خلال شراكاتنا مع خبراء في مختلف التخصصات، نقدم نهجًا متكاملًا يضمن التنسيق والتنفيذ الفعال للمشاريع.","items":["دراسة الجدوى","تطوير الأراضي","إدارة التصميم","أعمال البناء","أعمال الصيانة"]},"projectCategories":{"eyebrow":"مشاريعنا","titleLine1":"مشاريعنا عبر","titleLine2":"قطاعين رئيسيين","description":"استكشف مشاريع FBS للمقاولات في القطاعين السكني والتجاري داخل المملكة العربية السعودية.","residential":{"title":"السكني","description":"مشاريع سكنية متكاملة تركز على الجودة والراحة والقيمة طويلة الأمد."},"commercial":{"title":"التجاري","description":"مشاريع تجارية يتم تنفيذها بكفاءة ودقة وفهم واضح لاحتياجات الأعمال."}},"projectMap":{"selectedProjectLabel":"المشروع المحدد","photoPinHint":"اختر صورة المشروع للاطلاع على تفاصيله.","photoPositionNote":"مواضع الصور وخطوط الربط توضيحية، وليست إحداثيات دقيقة للمشاريع.","projectSingular":"مشروع","projectPlural":"مشاريع","countryLabel":"المملكة العربية السعودية","eyebrow":"نطاق مشاريعنا","titleLine1":"نبني في مختلف","titleLine2":"مناطق المملكة","description":"استكشف مجموعة مختارة من مشاريع FBS للمقاولات في خمس مناطق بالمملكة العربية السعودية.","viewProject":"عرض المشروع","projects":{"riyadh":{"title":"جوهرة السحاب","type":"سكني","location":"الرياض"},"jeddah":{"title":"نزل خيالا","type":"سكني","location":"جدة"},"madinah":{"title":"نزل الدار","type":"سكني","location":"المدينة المنورة"},"taif":{"title":"ملفى الحوية","type":"سكني","location":"الطائف"},"tabuk":{"title":"ملفى تبوك هيلز","type":"سكني","location":"تبوك"}}},"vision2030":{"eyebrow":"رؤية السعودية 2030","titleLine1":"نساهم في بناء","titleLine2":"مملكة مزدهرة","description":"تساهم FBS للمقاولات في دعم تطلعات المملكة التنموية من خلال تنفيذ مشاريع تدعم النمو المستدام والمجتمعات القوية والقيمة طويلة الأمد.","cta":"اكتشف رؤية السعودية 2030"},"values":{"eyebrow":"قيمنا","titleLine1":"قيم تقود","titleLine2":"طريقة عملنا","description":"تعرّف على القيم الأساسية الست التي توجه أعمال شركة FBS للمقاولات.","items":{"integrity":{"title":"النزاهة","description":"نعمل بشفافية ومسؤولية واحترام في جميع علاقاتنا المهنية."},"quality":{"title":"الجودة","description":"نحافظ على معايير عالية في جميع مراحل تنفيذ المشروع."},"collaboration":{"title":"التعاون","description":"نوحد فرق العمل والتخصصات والشركاء لتحقيق أهداف المشروع المشتركة."},"responsibility":{"title":"المسؤولية","description":"نتعامل مع كل مشروع باهتمام بالإنسان والمجتمع والأثر طويل الأمد."}}},"sustainability":{"eyebrow":"الاستدامة","titleLine1":"نبني بمسؤولية","titleLine2":"تمتد للمستقبل","description":"يراعي نهجنا المسؤولية البيئية والاجتماعية والاقتصادية كجزء من تحقيق قيمة طويلة الأمد من خلال المشاريع التي ننفذها.","cta":"اكتشف الاستدامة","items":{"environmental":{"title":"المسؤولية البيئية","description":"دعم ممارسات أكثر مسؤولية في تنفيذ المشاريع مع الاهتمام بالموارد والكفاءة والأثر البيئي طويل الأمد."},"social":{"title":"المسؤولية الاجتماعية","description":"خلق قيمة للأفراد والمجتمعات من خلال التنفيذ المسؤول والتعاون الفعّال في المشاريع."},"economic":{"title":"المسؤولية الاقتصادية","description":"المساهمة في النمو المستدام من خلال كفاءة التنفيذ وتعزيز القيمة المحلية والأداء طويل الأمد."}}},"contactCta":{"eyebrow":"ابدأ التواصل معنا","titleLine1":"لديك مشروع","titleLine2":"تريد تنفيذه؟","description":"تواصل مع FBS للمقاولات لمناقشة متطلبات مشروعك والتعرف على فرص التعاون معنا.","primaryCta":"تواصل معنا"}}' where not exists (select 1 from public.content_translations where content_id = '3b5f183d-2a0a-5335-a21f-b5e8044cba54' and language_code = 'ar') on conflict do nothing;
