insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select '163790b9-f9ae-5193-a77a-4021ffad04b4','page','about-who-we-are','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = '163790b9-f9ae-5193-a77a-4021ffad04b4') on conflict do nothing;
insert into public.pages (id,route_path) select '163790b9-f9ae-5193-a77a-4021ffad04b4','about/who-we-are' where not exists (select 1 from public.pages where id = '163790b9-f9ae-5193-a77a-4021ffad04b4') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '163790b9-f9ae-5193-a77a-4021ffad04b4','en','Who We Are','{"eyebrow":"About Us","title":"Who We Are","introduction":"FBS Contracting Company is a leading construction company dedicated to delivering exceptional construction services. With a strong focus on quality, innovation, and client satisfaction, we have established ourselves as a trusted partner in the industry.","uniqueness":"At FBS Contracting, we understand that each project is unique, and we approach every endeavor with a commitment to excellence.","values":"Our core values of integrity, professionalism, and collaboration are at the heart of everything we do.","safety":"Safety is our top priority. We adhere to the highest industry standards and implement stringent safety protocols to ensure the well-being of our team members, clients, and the community.","expertise":"Whatever the project type, size, or location, we have the expertise, resources, and passion to bring your vision to life. Our team is committed to providing personalized service, working closely with you every step of the way to ensure your project’s success.","closing":"Thank you for considering FBS Contracting for your construction needs."}' where not exists (select 1 from public.content_translations where content_id = '163790b9-f9ae-5193-a77a-4021ffad04b4' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '163790b9-f9ae-5193-a77a-4021ffad04b4','ar','من نحن؟','{"eyebrow":"من نحن","title":"من نحن؟","introduction":"شركة FBS للمقاولات هي شركة إنشاءات رائدة متخصصة في تقديم خدمات بناء استثنائية. مع التركيز القوي على الجودة والابتكار ورضا العملاء، أنشأنا أنفسنا كشريك موثوق به في هذه الصناعة.","uniqueness":"في FBS للمقاولات، ندرك أن كل مشروع فريد من نوعه، ونتعامل مع كل مسعى مع الالتزام بالتميز.","values":"إن قيمنا الأساسية المتمثلة في النزاهة والكفاءة المهنية والتعاون هي جوهر كل ما نقوم به.","safety":"السلامة هي أولويتنا القصوى. نحن نلتزم بأعلى معايير الصناعة وننفذ بروتوكولات أمان صارمة لضمان رفاهية أعضاء فريقنا وعملائنا والمجتمع.","expertise":"مهما كان نوع المشروع أو حجمه أو موقعه، فلدينا الخبرة والموارد والشغف لتحقيق رؤيتك على أرض الواقع. يلتزم فريقنا بتقديم خدمة مخصصة، ويعمل معك بشكل وثيق في كل خطوة على الطريق لضمان نجاح مشروعك.","closing":"نشكرك على اهتمامك بشركة FBS للمقاولات لتلبية احتياجات البناء الخاصة بك."}' where not exists (select 1 from public.content_translations where content_id = '163790b9-f9ae-5193-a77a-4021ffad04b4' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select '163790b9-f9ae-5193-a77a-4021ffad04b4','src/contracting/site/i18n/{en,ar}.ts#innerPages.about.whoWeAre',null,null,'corporate-v2:page:about-who-we-are','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = '163790b9-f9ae-5193-a77a-4021ffad04b4') on conflict do nothing;
insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select 'a327ba6d-c35e-5d3e-afc0-7e04c6575457','page','about-chairman-speech','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = 'a327ba6d-c35e-5d3e-afc0-7e04c6575457') on conflict do nothing;
insert into public.pages (id,route_path) select 'a327ba6d-c35e-5d3e-afc0-7e04c6575457','about/chairman-speech' where not exists (select 1 from public.pages where id = 'a327ba6d-c35e-5d3e-afc0-7e04c6575457') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select 'a327ba6d-c35e-5d3e-afc0-7e04c6575457','en','Chairman Speech','{"eyebrow":"About Us","title":"Chairman Speech","body":["Building on our accumulated experience and continuous ambition, FBS Contracting continues its journey toward strengthening its position as a trusted partner in the construction and contracting sector, delivering projects distinguished by quality, efficiency, and commitment.","We believe that our success is measured not only by the scale of the projects we deliver, but also by the quality of our work, the reliability of our commitments, and our ability to build long-term relationships and partnerships with our clients.","As the construction sector continues to evolve, we remain committed to strengthening our capabilities and expertise, investing in our people, and contributing to the Kingdom of Saudi Arabia’s ongoing journey of development and growth.","We move forward with confidence, guided by our commitment to quality, excellence, and safety, while continuing to pursue sustainable growth and further strengthen FBS Contracting’s position in the construction industry."],"name":"Faisal Bin Saedan","role":"Chairman"}' where not exists (select 1 from public.content_translations where content_id = 'a327ba6d-c35e-5d3e-afc0-7e04c6575457' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select 'a327ba6d-c35e-5d3e-afc0-7e04c6575457','ar','كلمة رئيس مجلس الإدارة','{"eyebrow":"من نحن","title":"كلمة رئيس مجلس الإدارة","body":["انطلاقًا من خبراتنا المتراكمة وطموحنا المستمر، تواصل شركة FBS للمقاولات مسيرتها نحو تعزيز مكانتها كشريك موثوق في قطاع المقاولات والتشييد، من خلال تقديم مشاريع تتميز بالجودة والكفاءة والالتزام.","نؤمن بأن نجاحنا لا يقاس بحجم المشاريع التي ننفذها فحسب، بل بجودة أعمالنا، وموثوقية التزاماتنا، وقدرتنا على بناء علاقات وشراكات طويلة الأمد مع عملائنا.","ومع ما يشهده قطاع المقاولات من تطور متسارع، نواصل تعزيز قدراتنا وكفاءاتنا، والاستثمار في كوادرنا وخبراتنا، لنكون جزءًا فاعلًا في مسيرة التنمية والبناء في المملكة العربية السعودية.","ونمضي بثقة نحو المستقبل، ملتزمين بالجودة والتميز والسلامة، ومواصلين جهودنا لتحقيق نمو مستدام وتعزيز مكانة FBS للمقاولات في قطاع المقاولات."],"name":"فيصل بن سعيدان","role":"رئيس مجلس الإدارة"}' where not exists (select 1 from public.content_translations where content_id = 'a327ba6d-c35e-5d3e-afc0-7e04c6575457' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select 'a327ba6d-c35e-5d3e-afc0-7e04c6575457','src/contracting/site/i18n/{en,ar}.ts#innerPages.about.chairmanSpeech',null,null,'corporate-v2:page:about-chairman-speech','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = 'a327ba6d-c35e-5d3e-afc0-7e04c6575457') on conflict do nothing;
insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select '230c4390-58c1-5898-aeee-89960c3d3399','page','about-ceo-message','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = '230c4390-58c1-5898-aeee-89960c3d3399') on conflict do nothing;
insert into public.pages (id,route_path) select '230c4390-58c1-5898-aeee-89960c3d3399','about/ceo-message' where not exists (select 1 from public.pages where id = '230c4390-58c1-5898-aeee-89960c3d3399') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '230c4390-58c1-5898-aeee-89960c3d3399','en','CEO Speech','{"eyebrow":"About Us","title":"CEO Speech","body":["Praise be to Allah, Lord of the Worlds, and prayers and peace be upon the most honorable of the prophets and messengers, our Prophet Muhammad, and upon all his family and companions.","There is no doubt that the journey of a thousand miles begins with a single step, and to develop our present, we must set a clear vision for our future and continue to strive to improve our performance, find the best, and search for new opportunities to increase our activities within the Kingdom of Saudi Arabia in accordance with the Kingdom’s wise vision 2030.","Therefore, I pray to Allah Almighty that FBS Contracting Company will continue its journey and contribution to flourish our national economy and promote development for our children and society in order to achieve the vision.","In view of the giant construction boom that the Kingdom of Saudi Arabia is witnessing in the field of housing and the increasing demand in the construction market, the company has sought to provide everything that is finest and best in terms of speed and completion of projects, so this company was born.","To provide our esteemed customers with the best and highest quality, as well as accuracy in adhering to project delivery dates by providing a full team of engineers, consultants and contractors who have experience and high efficiency in this field, thus seeking to distinguish ourselves from other contracting companies and institutions by providing the best, and this is what our esteemed customers deserve."],"name":"Nawaf Binshuail","role":"CEO"}' where not exists (select 1 from public.content_translations where content_id = '230c4390-58c1-5898-aeee-89960c3d3399' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '230c4390-58c1-5898-aeee-89960c3d3399','ar','كلمة الرئيس التنفيذي','{"eyebrow":"من نحن","title":"كلمة الرئيس التنفيذي","body":["الحمد لله رب العالمين، والصلاة والسلام على أشرف الأنبياء والمرسلين، نبينا محمد وعلى آله وصحبه أجمعين.","مما لا شك فيه أن رحلة الألف ميل تبدأ بخطوة واحدة، ولتطوير حاضرنا، لا بد من وضع رؤية واضحة لمستقبلنا، ومواصلة السعي لتحسين أداء عملنا، والبحث عن الأفضل وفرص جديدة لزيادة أنشطتنا داخل المملكة العربية السعودية بما يتوافق مع رؤية المملكة الطموحة 2030.","لذا، أدعو الله عز وجل أن تواصل شركة إف بي إس (FBS) للمقاولات مسيرتها ومساهمتها في ازدهار اقتصادنا الوطني وتعزيز التنمية لأبنائنا ومجتمعنا تحليقاً نحو تحقيق الرؤية.","وفي ظل النهضة العمرانية العملاقة التي تشهدها المملكة العربية السعودية في مجال الإسكان والطلب المتزايد في سوق الإنشاءات، سعت الشركة إلى تقديم كل ما هو أفضل وأجود من حيث السرعة وإنجاز المشاريع، ومن هنا ولدت هذه الشركة.","لتقديم الأفضل وأعلى مستويات الجودة لعملائنا الكرام، فضلاً عن الدقة والالتزام بمواعيد تسليم المشاريع، وذلك من خلال توفير فريق كامل من المهندسين والاستشاريين والمقاولين ذوي الخبرة والكفاءة العالية في هذا المجال، سعياً منا للتميز عن باقي شركات ومؤسسات المقاولات الأخرى وتقديم الأفضل دائماً، وهو ما يستحقه عملاؤنا الكرام."],"name":"نواف بن شعيل","role":"الرئيس التنفيذي"}' where not exists (select 1 from public.content_translations where content_id = '230c4390-58c1-5898-aeee-89960c3d3399' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select '230c4390-58c1-5898-aeee-89960c3d3399','src/contracting/site/i18n/{en,ar}.ts#innerPages.about.ceoSpeech',null,null,'corporate-v2:page:about-ceo-message','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = '230c4390-58c1-5898-aeee-89960c3d3399') on conflict do nothing;
insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select '35dcf921-e112-5ea0-a5fa-e7bb04fd4a09','page','about-why-fbs-contracting','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = '35dcf921-e112-5ea0-a5fa-e7bb04fd4a09') on conflict do nothing;
insert into public.pages (id,route_path) select '35dcf921-e112-5ea0-a5fa-e7bb04fd4a09','about/why-fbs-contracting' where not exists (select 1 from public.pages where id = '35dcf921-e112-5ea0-a5fa-e7bb04fd4a09') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '35dcf921-e112-5ea0-a5fa-e7bb04fd4a09','en','Why FBS Contracting?','{"eyebrow":"About Us","title":"Why FBS Contracting?","features":[{"title":"Experience and Expertise","description":"Our clients benefit from our extensive experience in the contracting industry as we have successfully completed numerous projects of varying complexities, demonstrating our ability to handle any challenge that may arise."},{"title":"Commitment to Quality","description":"We maintain rigorous quality control measures to ensure that our projects meet the highest standards. Our attention to detail and dedication to craftsmanship result in outstanding results that stand the test of time."},{"title":"Client-Centric Approach","description":"Our clients are at the forefront of everything we do where we believe in fostering strong and collaborative relationships built on trust and open communication."},{"title":"Safety First","description":"Our team undergoes regular safety training, ensuring a safe working environment for all through mitigating risks and creating a secure environment for everyone involved."},{"title":"Innovative Solutions","description":"We leverage cutting-edge technologies, sustainable practices, and modern construction methodologies to optimize project efficiency and minimize environmental impact which allows us to deliver cost-effective solutions without compromising quality."},{"title":"Strong Supplier and Partner Network","description":"Over the years, we have built robust relationships with trusted suppliers and industry partners. Our network of trusted suppliers and industry partners enables us to access high-quality materials, resources, and specialized expertise, enhancing the overall project delivery process."}]}' where not exists (select 1 from public.content_translations where content_id = '35dcf921-e112-5ea0-a5fa-e7bb04fd4a09' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '35dcf921-e112-5ea0-a5fa-e7bb04fd4a09','ar','لماذا FBS للمقاولات؟','{"eyebrow":"من نحن","title":"لماذا FBS للمقاولات؟","features":[{"title":"الخبرة والكفاءة","description":"يستفيد عملاؤنا من خبرتنا الواسعة في مجال المقاولات. لقد أنجزنا بنجاح العديد من المشاريع ذات التعقيدات المختلفة، مما يدل على قدرتنا على التعامل مع أي تحد قد ينشأ."},{"title":"الالتزام بالجودة","description":"نحن نحافظ على تدابير صارمة لمراقبة الجودة لضمان تلبية مشاريعنا أعلى المعايير. اهتمامنا بالتفاصيل والتفاني في الحرفية يؤدي إلى نتائج باهرة تصمد أمام اختبار الزمن."},{"title":"التركيز على العملاء","description":"عملاؤنا هم في طليعة كل ما نقوم به، حيث نؤمن بتعزيز العلاقات القوية والتعاونية المبنية على الثقة والتواصل المفتوح."},{"title":"السلامة أولًا","description":"يخضع فريقنا لتدريب منتظم على السلامة، مما يضمن بيئة عمل آمنة للجميع من خلال تخفيف المخاطر وخلق بيئة آمنة لجميع المعنيين."},{"title":"الحلول المبتكرة","description":"نستفيد من التقنيات المتطورة والممارسات المستدامة ومنهجيات البناء الحديثة لتعزيز كفاءة المشاريع وتقليل الأثر البيئي، مع تقديم حلول فعالة من حيث التكلفة دون المساس بالجودة."},{"title":"شبكة الموردين والشركاء القوية","description":"على مر السنين، بنينا علاقات قوية مع موردين موثوقين وشركاء في القطاع، مما يتيح لنا الوصول إلى مواد عالية الجودة وخبرات متخصصة وتعزيز كفاءة تنفيذ المشاريع."}]}' where not exists (select 1 from public.content_translations where content_id = '35dcf921-e112-5ea0-a5fa-e7bb04fd4a09' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select '35dcf921-e112-5ea0-a5fa-e7bb04fd4a09','src/contracting/site/i18n/{en,ar}.ts#innerPages.about.whyFbs',null,null,'corporate-v2:page:about-why-fbs-contracting','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = '35dcf921-e112-5ea0-a5fa-e7bb04fd4a09') on conflict do nothing;
