insert into public.content_translations (content_id,language_code,title,content) select '60ccb2aa-5938-5098-a6e8-65e36765db3d','en','Vision & Mission','{"eyebrow":"About Us","title":"Vision & Mission","vision":{"title":"Our Vision","description":"To be among the top leading construction companies as a brand recognized for quality and innovation, supporting our employees and the clients we work for, by being their first choice contractor."},"mission":{"title":"Our Mission","description":"Providing safe and sustainable projects and services that support our core values and achieve our clients’ goals."},"objectives":{"title":"Our Objectives","items":["Establish and maintain standard practice methods in the construction industry.","Maintaining a progressive and competitive construction industry.","Facilitating harmonious industry-consumer relations."]}}' where not exists (select 1 from public.content_translations where content_id = '60ccb2aa-5938-5098-a6e8-65e36765db3d' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '60ccb2aa-5938-5098-a6e8-65e36765db3d','ar','الرؤية والرسالة','{"eyebrow":"من نحن","title":"الرؤية والرسالة","vision":{"title":"رؤيتنا","description":"أن نكون من بين أفضل شركات البناء الرائدة كعلامة تجارية معروفة بالجودة والابتكار، ودعم موظفينا والعملاء الذين نعمل لديهم، من خلال كوننا الخيار الأول لهم."},"mission":{"title":"رسالتنا","description":"تقديم مشاريع وخدمات آمنة ومستدامة تدعم قيمنا الأساسية وتحقق أهداف عملائنا."},"objectives":{"title":"أهدافنا","items":["إنشاء والحفاظ على أساليب الممارسة القياسية في صناعة البناء والتشييد.","الحفاظ على صناعة البناء التقدمية والتنافسية.","تسهيل العلاقات المتناغمة بين الصناعة والمستهلك."]}}' where not exists (select 1 from public.content_translations where content_id = '60ccb2aa-5938-5098-a6e8-65e36765db3d' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select '60ccb2aa-5938-5098-a6e8-65e36765db3d','src/contracting/site/i18n/{en,ar}.ts#innerPages.about.visionMission',null,null,'corporate-v2:page:about-vision-mission','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = '60ccb2aa-5938-5098-a6e8-65e36765db3d') on conflict do nothing;
insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select '537dccc6-6b0b-5ca0-a898-b62595055fa6','page','about-saudi-vision-2030','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = '537dccc6-6b0b-5ca0-a898-b62595055fa6') on conflict do nothing;
insert into public.pages (id,route_path) select '537dccc6-6b0b-5ca0-a898-b62595055fa6','about/saudi-vision-2030' where not exists (select 1 from public.pages where id = '537dccc6-6b0b-5ca0-a898-b62595055fa6') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '537dccc6-6b0b-5ca0-a898-b62595055fa6','en','Saudi Vision 2030','{"eyebrow":"About Us","title":"Saudi Vision 2030","statement":"By committing to Vision 2030 principles, we aim to contribute to the successful implementation of Saudi Vision 2030 and play an active role in the sustainable development of Saudi Arabia.","description":"At FBS Contracting, we are committed to supporting and aligning with the goals and objectives of Saudi Vision 2030. We recognize the significance of this transformative vision in shaping the future of Saudi Arabia and the construction industry. As such, we pledge to contribute to the realization of Saudi Vision 2030 through the following commitments:","commitmentsTitle":"Our Commitments","commitments":["Supporting Economic Diversification","Promoting Local Employment and Skills Development","Embracing Innovation and Technology","Adopting Sustainable Practices"]}' where not exists (select 1 from public.content_translations where content_id = '537dccc6-6b0b-5ca0-a898-b62595055fa6' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '537dccc6-6b0b-5ca0-a898-b62595055fa6','ar','رؤية السعودية 2030','{"eyebrow":"من نحن","title":"رؤية السعودية 2030","statement":"من خلال الالتزام بمبادئ رؤية 2030، نهدف إلى المساهمة في التنفيذ الناجح لرؤية السعودية 2030 ولعب دور فاعل في التنمية المستدامة في المملكة العربية السعودية.","description":"في FBS للمقاولات، نحن ملتزمون بدعم أهداف وغايات رؤية السعودية 2030 والمواءمة معها. ونحن ندرك أهمية هذه الرؤية التحويلية في تشكيل مستقبل المملكة العربية السعودية وصناعة البناء والتشييد. ومن هذا المنطلق، فإننا نتعهد بالمساهمة في تحقيق رؤية المملكة العربية السعودية 2030 من خلال الالتزامات التالية:","commitmentsTitle":"التزاماتنا","commitments":["دعم التنويع الاقتصادي","تعزيز العمالة المحلية وتنمية المهارات","احتضان الابتكار والتكنولوجيا","اعتماد الممارسات المستدامة"]}' where not exists (select 1 from public.content_translations where content_id = '537dccc6-6b0b-5ca0-a898-b62595055fa6' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select '537dccc6-6b0b-5ca0-a898-b62595055fa6','src/contracting/site/i18n/{en,ar}.ts#innerPages.about.saudiVision2030',null,null,'corporate-v2:page:about-saudi-vision-2030','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = '537dccc6-6b0b-5ca0-a898-b62595055fa6') on conflict do nothing;
