insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select '33c3896f-42bb-54e2-ab19-4b73b54988cc','page','sustainability-environmental-responsibility','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = '33c3896f-42bb-54e2-ab19-4b73b54988cc') on conflict do nothing;
insert into public.pages (id,route_path) select '33c3896f-42bb-54e2-ab19-4b73b54988cc','sustainability/environmental-responsibility' where not exists (select 1 from public.pages where id = '33c3896f-42bb-54e2-ab19-4b73b54988cc') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '33c3896f-42bb-54e2-ab19-4b73b54988cc','en','Environmental Responsibility','{"eyebrow":"Sustainability","title":"Environmental Responsibility","introduction":"FBS Contracting is committed to protecting the environment through sustainable practices and the continual improvement of its Environmental Management System. Our environmental policy provides a framework for setting objectives, improving performance, and meeting applicable environmental requirements.","commitmentsTitle":"Our Environmental Commitments","commitments":[{"title":"Environmental Protection","description":"Minimizing environmental impact by preventing pollution, reducing waste, conserving resources, and protecting the natural environment."},{"title":"Compliance Obligations","description":"Meeting applicable environmental laws, regulations, and other relevant requirements to support responsible operations."},{"title":"Continual Improvement","description":"Improving environmental performance through objectives, regular audits, and corrective and preventive actions."},{"title":"Sustainable Resource Use","description":"Focusing on responsible resource use and energy efficiency, with the aim of reducing our carbon footprint."},{"title":"Biodiversity and Ecosystems Protection","description":"Considering the environmental impacts of our activities and taking measures to mitigate adverse effects on biodiversity and ecosystems."}],"closing":"Environmental stewardship and sustainable development are integral to our environmental policy."}' where not exists (select 1 from public.content_translations where content_id = '33c3896f-42bb-54e2-ab19-4b73b54988cc' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '33c3896f-42bb-54e2-ab19-4b73b54988cc','ar','المسؤولية البيئية','{"eyebrow":"الاستدامة","title":"المسؤولية البيئية","introduction":"تلتزم شركة FBS للمقاولات بحماية البيئة من خلال الممارسات المستدامة والتحسين المستمر لنظام الإدارة البيئية. وتوفر سياستنا البيئية إطارًا لتحديد الأهداف وتحسين الأداء والالتزام بالمتطلبات البيئية المعمول بها.","commitmentsTitle":"التزاماتنا البيئية","commitments":[{"title":"حماية البيئة","description":"تقليل التأثير البيئي من خلال منع التلوث والحد من النفايات والحفاظ على الموارد وحماية البيئة الطبيعية."},{"title":"الالتزام بالمتطلبات البيئية","description":"الالتزام بالقوانين واللوائح والمتطلبات البيئية ذات الصلة لضمان تنفيذ العمليات بصورة مسؤولة."},{"title":"التحسين المستمر","description":"تحسين الأداء البيئي من خلال تحديد الأهداف وإجراء عمليات التدقيق المنتظمة وتنفيذ الإجراءات التصحيحية والوقائية."},{"title":"الاستخدام المستدام للموارد","description":"التركيز على الاستخدام المسؤول للموارد وكفاءة الطاقة بهدف تقليل البصمة الكربونية للشركة."},{"title":"حماية التنوع البيولوجي والنظم البيئية","description":"مراعاة التأثيرات البيئية للأنشطة واتخاذ التدابير اللازمة للتخفيف من الآثار السلبية على التنوع البيولوجي والنظم البيئية."}],"closing":"تُعد حماية البيئة والتنمية المستدامة جزءًا أساسيًا من التزام الشركة بسياستها البيئية."}' where not exists (select 1 from public.content_translations where content_id = '33c3896f-42bb-54e2-ab19-4b73b54988cc' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select '33c3896f-42bb-54e2-ab19-4b73b54988cc','src/contracting/site/i18n/{en,ar}.ts#innerPages.sustainability.environmental',null,null,'corporate-v2:page:sustainability-environmental-responsibility','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = '33c3896f-42bb-54e2-ab19-4b73b54988cc') on conflict do nothing;
insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select '59ea870e-a60c-52fe-ae4b-99b0c255a871','page','sustainability-social-responsibility','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = '59ea870e-a60c-52fe-ae4b-99b0c255a871') on conflict do nothing;
insert into public.pages (id,route_path) select '59ea870e-a60c-52fe-ae4b-99b0c255a871','sustainability/social-responsibility' where not exists (select 1 from public.pages where id = '59ea870e-a60c-52fe-ae4b-99b0c255a871') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '59ea870e-a60c-52fe-ae4b-99b0c255a871','en','Social Responsibility','{"eyebrow":"Sustainability","title":"Social Responsibility","introduction":"At FBS Contracting, the well-being of people, workplace safety, employee development and strong stakeholder relationships are important aspects of our approach to responsible construction.","commitmentsTitle":"Our Social Priorities","commitments":[{"title":"Health and Safety","description":"We are committed to providing safe and healthy working conditions for employees, contractors and visitors through risk assessment, preventive measures and continual improvement."},{"title":"Local Employment and Skills","description":"As part of our commitment to Saudi Vision 2030, we support local employment and skills development."},{"title":"Employee Engagement","description":"We recognize the importance of competent, well-trained and engaged employees, and support their participation in improving our management systems."},{"title":"Stakeholder Relationships","description":"We aim to maintain collaborative relationships with customers, employees, suppliers and other stakeholders, while considering the well-being of the communities connected to our work."}],"closing":"Our approach places people, safety, skills development and responsible relationships at the center of long-term progress."}' where not exists (select 1 from public.content_translations where content_id = '59ea870e-a60c-52fe-ae4b-99b0c255a871' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '59ea870e-a60c-52fe-ae4b-99b0c255a871','ar','المسؤولية الاجتماعية','{"eyebrow":"الاستدامة","title":"المسؤولية الاجتماعية","introduction":"تولي شركة FBS للمقاولات أهمية لسلامة الأفراد ورفاهيتهم، وتطوير مهارات الموظفين، وبناء علاقات قوية مع الأطراف المعنية، ضمن نهجها المسؤول في قطاع البناء والتشييد.","commitmentsTitle":"أولوياتنا الاجتماعية","commitments":[{"title":"الصحة والسلامة المهنية","description":"نلتزم بتوفير ظروف عمل آمنة وصحية للموظفين والمقاولين والزوار من خلال تقييم المخاطر والإجراءات الوقائية والتحسين المستمر."},{"title":"التوظيف المحلي وتنمية المهارات","description":"في إطار التزامنا برؤية السعودية 2030، ندعم تعزيز فرص التوظيف المحلي وتنمية المهارات."},{"title":"مشاركة الموظفين","description":"نؤمن بأهمية الموظفين المؤهلين والمدربين والمشاركين بفاعلية في تطوير وتحسين أنظمة الإدارة بالشركة."},{"title":"العلاقات مع الأطراف المعنية","description":"نسعى إلى الحفاظ على علاقات تعاونية مع العملاء والموظفين والموردين ومختلف الأطراف المعنية، مع مراعاة رفاهية المجتمعات المرتبطة بأعمالنا."}],"closing":"يرتكز نهجنا على الاهتمام بالإنسان والسلامة وتنمية المهارات والعلاقات المسؤولة لدعم التقدم على المدى الطويل."}' where not exists (select 1 from public.content_translations where content_id = '59ea870e-a60c-52fe-ae4b-99b0c255a871' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select '59ea870e-a60c-52fe-ae4b-99b0c255a871','src/contracting/site/i18n/{en,ar}.ts#innerPages.sustainability.social',null,null,'corporate-v2:page:sustainability-social-responsibility','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = '59ea870e-a60c-52fe-ae4b-99b0c255a871') on conflict do nothing;
insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select '5371eb73-857b-5e84-adb0-d668c65e8735','page','sustainability-economic-responsibility','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = '5371eb73-857b-5e84-adb0-d668c65e8735') on conflict do nothing;
insert into public.pages (id,route_path) select '5371eb73-857b-5e84-adb0-d668c65e8735','sustainability/economic-responsibility' where not exists (select 1 from public.pages where id = '5371eb73-857b-5e84-adb0-d668c65e8735') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '5371eb73-857b-5e84-adb0-d668c65e8735','en','Economic Responsibility','{"eyebrow":"Sustainability","title":"Economic Responsibility","introduction":"At FBS Contracting, our approach to economic responsibility is reflected in our commitment to supporting Saudi Vision 2030, delivering integrated construction services, managing resources efficiently, and building strong relationships with our partners.","commitmentsTitle":"Our Economic Priorities","commitments":[{"title":"Supporting Economic Diversification","description":"We are committed to supporting the economic diversification objectives of Saudi Vision 2030 and contributing to the Kingdom’s long-term development."},{"title":"Integrated Project Delivery","description":"Our comprehensive services cover different stages of the project lifecycle, supported by coordination across disciplines to improve the consistency of project planning and execution."},{"title":"Efficient Resource Management","description":"We adopt a process-based approach to managing activities and resources efficiently, with a focus on achieving effective and reliable project outcomes."},{"title":"Strong Supplier Relationships","description":"We seek to establish mutually beneficial relationships with suppliers and other stakeholders to strengthen cooperation and support the creation of long-term value."}],"closing":"Through integrated services, efficient operations, and responsible partnerships, we aim to support sustainable economic development."}' where not exists (select 1 from public.content_translations where content_id = '5371eb73-857b-5e84-adb0-d668c65e8735' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '5371eb73-857b-5e84-adb0-d668c65e8735','ar','المسؤولية الاقتصادية','{"eyebrow":"الاستدامة","title":"المسؤولية الاقتصادية","introduction":"تنعكس مسؤوليتنا الاقتصادية في شركة FBS للمقاولات من خلال التزامنا بدعم رؤية السعودية 2030، وتقديم خدمات إنشائية متكاملة، وإدارة الموارد بكفاءة، وبناء علاقات قوية مع شركائنا.","commitmentsTitle":"أولوياتنا الاقتصادية","commitments":[{"title":"دعم التنويع الاقتصادي","description":"نلتزم بدعم أهداف التنويع الاقتصادي لرؤية السعودية 2030 والمساهمة في التنمية طويلة الأمد بالمملكة."},{"title":"التنفيذ المتكامل للمشاريع","description":"نقدم خدمات شاملة تغطي المراحل المختلفة لدورة حياة المشروع، مع التنسيق بين التخصصات المختلفة لتعزيز تكامل التخطيط والتنفيذ."},{"title":"الإدارة الفعالة للموارد","description":"نعتمد نهجًا منظمًا لإدارة الأنشطة والموارد بكفاءة، مع التركيز على تحقيق نتائج فعالة وموثوقة في تنفيذ المشاريع."},{"title":"العلاقات القوية مع الموردين","description":"نسعى إلى بناء علاقات متبادلة المنفعة مع الموردين والأطراف المعنية لتعزيز التعاون ودعم تحقيق قيمة طويلة الأمد."}],"closing":"من خلال الخدمات المتكاملة وكفاءة العمليات والشراكات المسؤولة، نسعى إلى دعم التنمية الاقتصادية المستدامة."}' where not exists (select 1 from public.content_translations where content_id = '5371eb73-857b-5e84-adb0-d668c65e8735' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select '5371eb73-857b-5e84-adb0-d668c65e8735','src/contracting/site/i18n/{en,ar}.ts#innerPages.sustainability.economic',null,null,'corporate-v2:page:sustainability-economic-responsibility','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = '5371eb73-857b-5e84-adb0-d668c65e8735') on conflict do nothing;
insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select '5251a504-5a08-512b-a03f-487cb7a50669','page','sustainability-continuous-improvement','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = '5251a504-5a08-512b-a03f-487cb7a50669') on conflict do nothing;
insert into public.pages (id,route_path) select '5251a504-5a08-512b-a03f-487cb7a50669','sustainability/continuous-improvement' where not exists (select 1 from public.pages where id = '5251a504-5a08-512b-a03f-487cb7a50669') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '5251a504-5a08-512b-a03f-487cb7a50669','en','Continuous Improvement','{"eyebrow":"Sustainability","title":"Continuous Improvement","introduction":"At FBS Contracting, continual improvement is an important part of our quality, occupational health and safety, and environmental management policies. We are committed to reviewing objectives, evaluating performance, conducting audits, and implementing measures that support better outcomes.","systemsTitle":"Our Management Commitments","systems":[{"title":"Quality Management","description":"We are committed to continually improving our Quality Management System through reviewing quality objectives, conducting internal audits, and taking corrective and preventive actions to enhance performance and customer satisfaction."},{"title":"Occupational Health & Safety","description":"We strive to improve occupational health and safety performance through risk reduction, reviewing safety objectives, internal audits, corrective actions, and worker consultation and participation."},{"title":"Environmental Management","description":"We seek to improve environmental performance through environmental objectives, regular audits, and corrective and preventive actions, while supporting sustainable practices and responsible resource use."}],"approachTitle":"Our Improvement Approach","steps":[{"title":"Set and Review Objectives","description":"Establish and regularly review objectives aligned with our management policies and organizational direction."},{"title":"Evaluate and Audit","description":"Assess performance, conduct internal audits, and use relevant information to identify improvement needs."},{"title":"Take Corrective Action","description":"Address nonconformities and implement corrective and preventive measures to strengthen management processes."},{"title":"Support Ongoing Development","description":"Use evidence-based decisions and employee participation to support improvements across our operations."}],"closing":"Continuous improvement supports our commitment to quality, workplace safety, environmental responsibility and long-term organizational performance."}' where not exists (select 1 from public.content_translations where content_id = '5251a504-5a08-512b-a03f-487cb7a50669' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '5251a504-5a08-512b-a03f-487cb7a50669','ar','التحسين المستمر','{"eyebrow":"الاستدامة","title":"التحسين المستمر","introduction":"يمثل التحسين المستمر جزءًا مهمًا من سياسات شركة FBS للمقاولات في إدارة الجودة والصحة والسلامة المهنية والإدارة البيئية. ونلتزم بمراجعة الأهداف وتقييم الأداء وإجراء عمليات التدقيق وتنفيذ الإجراءات التي تدعم تحسين نتائج العمل.","systemsTitle":"التزاماتنا الإدارية","systems":[{"title":"إدارة الجودة","description":"نلتزم بالتحسين المستمر لنظام إدارة الجودة من خلال مراجعة أهداف الجودة وإجراء التدقيق الداخلي وتنفيذ الإجراءات التصحيحية والوقائية لتعزيز الأداء ورضا العملاء."},{"title":"الصحة والسلامة المهنية","description":"نسعى إلى تحسين أداء الصحة والسلامة المهنية من خلال الحد من المخاطر ومراجعة أهداف السلامة والتدقيق الداخلي والإجراءات التصحيحية ومشاركة العاملين والتشاور معهم."},{"title":"الإدارة البيئية","description":"نسعى إلى تحسين الأداء البيئي من خلال تحديد الأهداف البيئية وإجراء عمليات التدقيق المنتظمة وتنفيذ الإجراءات التصحيحية والوقائية ودعم الممارسات المستدامة والاستخدام المسؤول للموارد."}],"approachTitle":"منهجنا في التحسين المستمر","steps":[{"title":"تحديد الأهداف ومراجعتها","description":"تحديد الأهداف ومراجعتها بصورة منتظمة بما يتوافق مع سياسات الإدارة والتوجه العام للشركة."},{"title":"التقييم والتدقيق","description":"تقييم الأداء وإجراء عمليات التدقيق الداخلي والاستفادة من المعلومات المتاحة لتحديد فرص التحسين."},{"title":"اتخاذ الإجراءات التصحيحية","description":"معالجة حالات عدم المطابقة وتنفيذ الإجراءات التصحيحية والوقائية لتعزيز كفاءة العمليات الإدارية."},{"title":"دعم التطوير المستمر","description":"الاستفادة من القرارات المبنية على الأدلة ومشاركة الموظفين لدعم تحسين العمليات المختلفة."}],"closing":"يدعم التحسين المستمر التزامنا بالجودة وسلامة بيئة العمل والمسؤولية البيئية وتطوير الأداء المؤسسي على المدى الطويل."}' where not exists (select 1 from public.content_translations where content_id = '5251a504-5a08-512b-a03f-487cb7a50669' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select '5251a504-5a08-512b-a03f-487cb7a50669','src/contracting/site/i18n/{en,ar}.ts#innerPages.sustainability.continuousImprovement',null,null,'corporate-v2:page:sustainability-continuous-improvement','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = '5251a504-5a08-512b-a03f-487cb7a50669') on conflict do nothing;
insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select 'a688ac64-c323-5ea1-af62-1e6160cd3a3a','page','business-continuity-risk-assessment-management','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = 'a688ac64-c323-5ea1-af62-1e6160cd3a3a') on conflict do nothing;
insert into public.pages (id,route_path) select 'a688ac64-c323-5ea1-af62-1e6160cd3a3a','business-continuity/risk-assessment-management' where not exists (select 1 from public.pages where id = 'a688ac64-c323-5ea1-af62-1e6160cd3a3a') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select 'a688ac64-c323-5ea1-af62-1e6160cd3a3a','en','Risk Assessment and Management','{"eyebrow":"Business Continuity","title":"Risk Assessment and Management","introduction":"FBS Contracting is committed to maintaining a resilient and adaptive Business Continuity Management System. Our approach emphasizes identifying and mitigating potential risks, preparing for disruptions, and supporting the continued delivery of our products and services.","focusTitle":"Our Approach to Risk Management","focusAreas":[{"title":"Risk Identification and Mitigation","description":"Our Business Continuity Policy emphasizes identifying potential risks and taking measures to mitigate them as part of organizational preparedness."},{"title":"Preparedness and Response","description":"We are committed to strengthening resilience through preparing for, responding to, and recovering from disruptions."},{"title":"Compliance Obligations","description":"We commit to meeting applicable legal and other requirements related to business continuity to support responsible operations."},{"title":"Resource Availability","description":"Personnel, technology, infrastructure, and financial resources are important elements in supporting our business continuity strategies and solutions."}],"closing":"These principles support our commitment to business continuity, preparedness, and organizational resilience."}' where not exists (select 1 from public.content_translations where content_id = 'a688ac64-c323-5ea1-af62-1e6160cd3a3a' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select 'a688ac64-c323-5ea1-af62-1e6160cd3a3a','ar','تقييم المخاطر وإدارتها','{"eyebrow":"استمرارية الأعمال","title":"تقييم المخاطر وإدارتها","introduction":"تلتزم شركة FBS للمقاولات بالحفاظ على نظام مرن وقابل للتكيف لإدارة استمرارية الأعمال. ويركز نهجنا على تحديد المخاطر المحتملة والحد منها، والاستعداد للاضطرابات، ودعم استمرار تقديم المنتجات والخدمات.","focusTitle":"نهجنا في إدارة المخاطر","focusAreas":[{"title":"تحديد المخاطر والحد منها","description":"تركز سياسة استمرارية الأعمال على تحديد المخاطر المحتملة واتخاذ التدابير اللازمة للحد منها كجزء من الاستعداد المؤسسي."},{"title":"الاستعداد والاستجابة","description":"نلتزم بتعزيز مرونة الأعمال من خلال الاستعداد للاضطرابات والاستجابة لها والتعافي من آثارها."},{"title":"الالتزام بالمتطلبات التنظيمية","description":"نلتزم بالمتطلبات القانونية والتنظيمية وغيرها من المتطلبات المرتبطة باستمرارية الأعمال لدعم تنفيذ العمليات بصورة مسؤولة."},{"title":"توافر الموارد","description":"تمثل الموارد البشرية والتكنولوجيا والبنية التحتية والموارد المالية عناصر مهمة لدعم استراتيجيات وحلول استمرارية الأعمال."}],"closing":"تدعم هذه المبادئ التزامنا باستمرارية الأعمال والاستعداد والمرونة المؤسسية."}' where not exists (select 1 from public.content_translations where content_id = 'a688ac64-c323-5ea1-af62-1e6160cd3a3a' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select 'a688ac64-c323-5ea1-af62-1e6160cd3a3a','src/contracting/site/i18n/{en,ar}.ts#innerPages.businessContinuity.riskAssessment',null,null,'corporate-v2:page:business-continuity-risk-assessment-management','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = 'a688ac64-c323-5ea1-af62-1e6160cd3a3a') on conflict do nothing;
