insert into public.content_translations (content_id,language_code,title,content) select '44bca10d-14e0-5e84-a686-b40b477bf753','en','Business Impact Analysis','{"eyebrow":"Business Continuity","title":"Business Impact Analysis","introduction":"Business Impact Analysis is an important aspect of the preparedness and resilience principles outlined in FBS Contracting’s Business Continuity Policy. It supports understanding the potential effects of disruptions and informs the development of appropriate recovery strategies.","focusTitle":"Our Business Continuity Priorities","focusAreas":[{"title":"Understanding Disruption Impact","description":"Our Business Continuity Policy recognizes the importance of conducting business impact analyses as part of preparing for potential disruptions."},{"title":"Supporting Service Continuity","description":"Our commitment to business continuity focuses on supporting the continued delivery of products and services during and after disruptions."},{"title":"Considering Resource Requirements","description":"Personnel, technology, infrastructure, and financial resources are identified as important elements in supporting business continuity strategies and solutions."},{"title":"Informing Recovery Strategies","description":"Business impact analysis contributes to organizational preparedness alongside risk identification, mitigation, and the development of effective recovery strategies."}],"closing":"Understanding the impact of potential disruptions supports our commitment to resilience, preparedness, and effective business continuity planning."}' where not exists (select 1 from public.content_translations where content_id = '44bca10d-14e0-5e84-a686-b40b477bf753' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '44bca10d-14e0-5e84-a686-b40b477bf753','ar','تحليل أثر تعطل الأعمال','{"eyebrow":"استمرارية الأعمال","title":"تحليل أثر تعطل الأعمال","introduction":"يمثل تحليل أثر تعطل الأعمال جانبًا مهمًا من مبادئ الاستعداد والمرونة الواردة في سياسة استمرارية الأعمال لدى شركة FBS للمقاولات. ويساعد على فهم الآثار المحتملة للاضطرابات ودعم تطوير استراتيجيات التعافي المناسبة.","focusTitle":"أولوياتنا في استمرارية الأعمال","focusAreas":[{"title":"فهم تأثير الاضطرابات","description":"تؤكد سياسة استمرارية الأعمال أهمية إجراء تحليلات أثر تعطل الأعمال كجزء من الاستعداد للاضطرابات المحتملة."},{"title":"دعم استمرارية الخدمات","description":"يركز التزامنا باستمرارية الأعمال على دعم مواصلة تقديم المنتجات والخدمات أثناء الاضطرابات وبعدها."},{"title":"مراعاة متطلبات الموارد","description":"تُعد الموارد البشرية والتكنولوجيا والبنية التحتية والموارد المالية عناصر مهمة في دعم استراتيجيات وحلول استمرارية الأعمال."},{"title":"دعم استراتيجيات التعافي","description":"يساهم تحليل أثر تعطل الأعمال في دعم الاستعداد المؤسسي إلى جانب تحديد المخاطر والحد منها وتطوير استراتيجيات تعافٍ فعالة."}],"closing":"يساهم فهم الآثار المحتملة للاضطرابات في دعم التزامنا بالمرونة والاستعداد والتخطيط الفعال لاستمرارية الأعمال."}' where not exists (select 1 from public.content_translations where content_id = '44bca10d-14e0-5e84-a686-b40b477bf753' and language_code = 'ar') on conflict do nothing;
