insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select '736092dc-bce2-5c05-acc2-a597c79ae8bb','page','business-continuity-plan-development','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = '736092dc-bce2-5c05-acc2-a597c79ae8bb') on conflict do nothing;
insert into public.pages (id,route_path) select '736092dc-bce2-5c05-acc2-a597c79ae8bb','business-continuity/plan-development' where not exists (select 1 from public.pages where id = '736092dc-bce2-5c05-acc2-a597c79ae8bb') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '736092dc-bce2-5c05-acc2-a597c79ae8bb','en','Plan Development','{"eyebrow":"Business Continuity","title":"Plan Development","introduction":"At FBS Contracting, our Business Continuity Policy provides a framework for organizational preparedness, response, and recovery. It emphasizes identifying potential risks, understanding the impact of disruptions, developing effective recovery strategies, and ensuring the availability of essential resources.","focusTitle":"Our Business Continuity Planning Principles","focusAreas":[{"title":"Risk and Impact Considerations","description":"Identifying potential risks and conducting business impact analyses are important foundations for developing effective business continuity strategies."},{"title":"Response and Recovery Strategies","description":"Our Business Continuity Policy emphasizes preparing for, responding to, and recovering from disruptions through appropriate recovery strategies."},{"title":"Resource and Stakeholder Requirements","description":"Business continuity planning considers the availability of personnel, technology, infrastructure, and financial resources, alongside the needs of customers, employees, suppliers, and regulatory authorities."},{"title":"Review and Continual Improvement","description":"We are committed to reviewing business continuity objectives, conducting audits, and implementing corrective and preventive actions to support continual improvement."}],"closing":"These planning principles support our commitment to organizational resilience and the continued delivery of products and services during and after disruptions."}' where not exists (select 1 from public.content_translations where content_id = '736092dc-bce2-5c05-acc2-a597c79ae8bb' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '736092dc-bce2-5c05-acc2-a597c79ae8bb','ar','تطوير الخطط','{"eyebrow":"استمرارية الأعمال","title":"تطوير الخطط","introduction":"توفر سياسة استمرارية الأعمال في شركة FBS للمقاولات إطارًا يدعم الاستعداد المؤسسي والاستجابة للاضطرابات والتعافي منها. وتركز على تحديد المخاطر المحتملة وفهم آثار تعطل الأعمال وتطوير استراتيجيات تعافٍ فعالة وضمان توافر الموارد الأساسية.","focusTitle":"مبادئ التخطيط لاستمرارية الأعمال","focusAreas":[{"title":"دراسة المخاطر وتأثيراتها","description":"يمثل تحديد المخاطر المحتملة وإجراء تحليلات أثر تعطل الأعمال أساسًا مهمًا لتطوير استراتيجيات فعالة لاستمرارية الأعمال."},{"title":"استراتيجيات الاستجابة والتعافي","description":"تؤكد سياسة استمرارية الأعمال أهمية الاستعداد للاضطرابات والاستجابة لها والتعافي منها من خلال استراتيجيات مناسبة."},{"title":"متطلبات الموارد والأطراف المعنية","description":"تراعي مبادئ التخطيط توافر الموارد البشرية والتكنولوجيا والبنية التحتية والموارد المالية، إلى جانب احتياجات العملاء والموظفين والموردين والجهات التنظيمية."},{"title":"المراجعة والتحسين المستمر","description":"نلتزم بمراجعة أهداف استمرارية الأعمال وإجراء عمليات التدقيق وتنفيذ الإجراءات التصحيحية والوقائية لدعم التحسين المستمر."}],"closing":"تدعم مبادئ التخطيط هذه التزامنا بالمرونة المؤسسية واستمرار تقديم المنتجات والخدمات أثناء الاضطرابات وبعدها."}' where not exists (select 1 from public.content_translations where content_id = '736092dc-bce2-5c05-acc2-a597c79ae8bb' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select '736092dc-bce2-5c05-acc2-a597c79ae8bb','src/contracting/site/i18n/{en,ar}.ts#innerPages.businessContinuity.planDevelopment',null,null,'corporate-v2:page:business-continuity-plan-development','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = '736092dc-bce2-5c05-acc2-a597c79ae8bb') on conflict do nothing;
insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select '8a7bfa9b-df5f-5f36-a188-1bf0ccad849c','page','business-continuity-recovery-restoration','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = '8a7bfa9b-df5f-5f36-a188-1bf0ccad849c') on conflict do nothing;
insert into public.pages (id,route_path) select '8a7bfa9b-df5f-5f36-a188-1bf0ccad849c','business-continuity/recovery-restoration' where not exists (select 1 from public.pages where id = '8a7bfa9b-df5f-5f36-a188-1bf0ccad849c') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '8a7bfa9b-df5f-5f36-a188-1bf0ccad849c','en','Recovery and Restoration','{"eyebrow":"Business Continuity","title":"Recovery and Restoration","introduction":"FBS Contracting is committed to strengthening its organizational resilience through preparedness, response, and recovery from disruptions. Our Business Continuity Policy emphasizes the development of effective recovery strategies and the availability of essential resources to support continued service delivery.","focusTitle":"Our Recovery and Restoration Principles","focusAreas":[{"title":"Preparedness and Response","description":"Our Business Continuity Policy emphasizes preparing for potential disruptions and responding to them as part of maintaining organizational resilience."},{"title":"Recovery Strategies","description":"We recognize the importance of developing effective recovery strategies informed by risk identification, mitigation, and business impact analysis."},{"title":"Availability of Essential Resources","description":"Personnel, technology, infrastructure, and financial resources are important elements in supporting business continuity and recovery solutions."},{"title":"Stakeholder Considerations","description":"Our approach considers the needs and expectations of customers, employees, suppliers, and regulatory authorities when supporting business continuity."}],"closing":"Through preparedness, effective recovery strategies, resource management, and continual improvement, we aim to strengthen resilience and support the continuity of our operations."}' where not exists (select 1 from public.content_translations where content_id = '8a7bfa9b-df5f-5f36-a188-1bf0ccad849c' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '8a7bfa9b-df5f-5f36-a188-1bf0ccad849c','ar','التعافي واستعادة الأعمال','{"eyebrow":"استمرارية الأعمال","title":"التعافي واستعادة الأعمال","introduction":"تلتزم شركة FBS للمقاولات بتعزيز مرونتها المؤسسية من خلال الاستعداد للاضطرابات والاستجابة لها والتعافي من آثارها. وتؤكد سياسة استمرارية الأعمال أهمية تطوير استراتيجيات تعافٍ فعالة وضمان توافر الموارد الأساسية لدعم استمرار تقديم الخدمات.","focusTitle":"مبادئ التعافي واستعادة الأعمال","focusAreas":[{"title":"الاستعداد والاستجابة","description":"تركز سياسة استمرارية الأعمال على الاستعداد للاضطرابات المحتملة والاستجابة لها باعتبار ذلك جزءًا من الحفاظ على المرونة المؤسسية."},{"title":"استراتيجيات التعافي","description":"نؤكد أهمية تطوير استراتيجيات تعافٍ فعالة تستند إلى تحديد المخاطر والحد منها وتحليل آثار تعطل الأعمال."},{"title":"توافر الموارد الأساسية","description":"تمثل الموارد البشرية والتكنولوجيا والبنية التحتية والموارد المالية عناصر مهمة لدعم استمرارية الأعمال وحلول التعافي."},{"title":"مراعاة الأطراف المعنية","description":"يراعي نهجنا احتياجات وتوقعات العملاء والموظفين والموردين والجهات التنظيمية عند دعم استمرارية الأعمال."}],"closing":"من خلال الاستعداد واستراتيجيات التعافي الفعالة وإدارة الموارد والتحسين المستمر، نسعى إلى تعزيز المرونة المؤسسية ودعم استمرارية عملياتنا."}' where not exists (select 1 from public.content_translations where content_id = '8a7bfa9b-df5f-5f36-a188-1bf0ccad849c' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select '8a7bfa9b-df5f-5f36-a188-1bf0ccad849c','src/contracting/site/i18n/{en,ar}.ts#innerPages.businessContinuity.recoveryRestoration',null,null,'corporate-v2:page:business-continuity-recovery-restoration','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = '8a7bfa9b-df5f-5f36-a188-1bf0ccad849c') on conflict do nothing;
insert into public.content_items (id,kind,slug,publication_status,approval_status,sort_order) select 'f5e99b3c-742d-57b5-a984-fa2dfb3d95ee','page','business-continuity-leadership-accountability','draft','unreviewed',0 where not exists (select 1 from public.content_items where id = 'f5e99b3c-742d-57b5-a984-fa2dfb3d95ee') on conflict do nothing;
insert into public.pages (id,route_path) select 'f5e99b3c-742d-57b5-a984-fa2dfb3d95ee','business-continuity/leadership-accountability' where not exists (select 1 from public.pages where id = 'f5e99b3c-742d-57b5-a984-fa2dfb3d95ee') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select 'f5e99b3c-742d-57b5-a984-fa2dfb3d95ee','en','Leadership and Accountability','{"eyebrow":"Business Continuity","title":"Leadership and Accountability","introduction":"At FBS Contracting, our Business Continuity Policy supports our strategic direction and provides a framework for business continuity objectives, responsible operations, and continual improvement. Organizational resilience is supported through appropriate resource management, compliance commitments, and engagement with relevant stakeholders.","focusTitle":"Our Governance Commitments","focusAreas":[{"title":"Strategic Direction and Objectives","description":"Our Business Continuity Policy supports the organization’s strategic direction and provides a framework for establishing and reviewing business continuity objectives."},{"title":"Compliance and Responsible Operations","description":"We are committed to meeting applicable legal and other requirements related to business continuity to support responsible operations and regulatory compliance."},{"title":"Resource Management","description":"We recognize the importance of ensuring the availability of personnel, technology, infrastructure, and financial resources to support business continuity strategies and solutions."},{"title":"Stakeholder Engagement and Improvement","description":"We are committed to considering the needs and expectations of customers, employees, suppliers, and regulatory authorities, alongside reviewing objectives, conducting audits, and supporting continual improvement."}],"closing":"Through clear organizational commitments, responsible resource management, stakeholder engagement, and continual improvement, we aim to strengthen business continuity and resilience."}' where not exists (select 1 from public.content_translations where content_id = 'f5e99b3c-742d-57b5-a984-fa2dfb3d95ee' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select 'f5e99b3c-742d-57b5-a984-fa2dfb3d95ee','ar','القيادة والمساءلة','{"eyebrow":"استمرارية الأعمال","title":"القيادة والمساءلة","introduction":"تدعم سياسة استمرارية الأعمال في شركة FBS للمقاولات التوجه الاستراتيجي للشركة، وتوفر إطارًا لتحديد أهداف استمرارية الأعمال وتعزيز العمليات المسؤولة والتحسين المستمر. كما تستند المرونة المؤسسية إلى الإدارة المناسبة للموارد والالتزام بالمتطلبات التنظيمية والتفاعل مع الأطراف المعنية.","focusTitle":"التزاماتنا في الحوكمة","focusAreas":[{"title":"التوجه الاستراتيجي والأهداف","description":"تدعم سياسة استمرارية الأعمال التوجه الاستراتيجي للشركة، وتوفر إطارًا لتحديد أهداف استمرارية الأعمال ومراجعتها."},{"title":"الالتزام والعمليات المسؤولة","description":"نلتزم بالمتطلبات القانونية والتنظيمية وغيرها من المتطلبات المتعلقة باستمرارية الأعمال، بما يدعم تنفيذ العمليات بصورة مسؤولة."},{"title":"إدارة الموارد","description":"نؤكد أهمية ضمان توافر الموارد البشرية والتكنولوجيا والبنية التحتية والموارد المالية اللازمة لدعم استراتيجيات وحلول استمرارية الأعمال."},{"title":"التفاعل مع الأطراف المعنية والتحسين","description":"نلتزم بمراعاة احتياجات وتوقعات العملاء والموظفين والموردين والجهات التنظيمية، إلى جانب مراجعة الأهداف وإجراء عمليات التدقيق ودعم التحسين المستمر."}],"closing":"من خلال الالتزامات المؤسسية الواضحة والإدارة المسؤولة للموارد والتفاعل مع الأطراف المعنية والتحسين المستمر، نسعى إلى تعزيز استمرارية الأعمال والمرونة المؤسسية."}' where not exists (select 1 from public.content_translations where content_id = 'f5e99b3c-742d-57b5-a984-fa2dfb3d95ee' and language_code = 'ar') on conflict do nothing;
insert into private.content_provenance (content_id,source_reference,source_snapshot,source_page,import_key,notes) select 'f5e99b3c-742d-57b5-a984-fa2dfb3d95ee','src/contracting/site/i18n/{en,ar}.ts#innerPages.businessContinuity.leadershipAccountability',null,null,'corporate-v2:page:business-continuity-leadership-accountability','Imported from the existing repository. Source document/version and business approval must be verified.' where not exists (select 1 from private.content_provenance where content_id = 'f5e99b3c-742d-57b5-a984-fa2dfb3d95ee') on conflict do nothing;
