insert into public.content_translations (content_id,language_code,title,content) select '3f39c119-6448-54a2-a488-018088a76a72','en','Careers','{"eyebrow":"Careers & Training","title":"Careers","introduction":"At FBS Contracting, we recognize the importance of talented people in delivering quality construction services. We value professionalism, collaboration, and continuous development as we work toward building a stronger future.","opportunitiesTitle":"Career Opportunities","noVacanciesTitle":"Explore Opportunities With Us","noVacanciesDescription":"Current job openings will be displayed here when announced. You can also prepare a general application using the form below.","formTitle":"Career Application","formDescription":"Tell us about yourself and share your professional experience.","nameLabel":"Full Name","emailLabel":"Email Address","subjectLabel":"Subject","messageLabel":"Your Message","cvLabel":"Attach Your CV / Resume","submitLabel":"Review Application","demoNotice":"Demo form only. Applications are not submitted or stored at this stage.","cvHint":"PDF, DOC or DOCX — Maximum 5 MB","invalidCvType":"Please select a PDF, DOC or DOCX file.","invalidCvSize":"The file must not exceed 5 MB.","reviewTitle":"Review Your Application","closeLabel":"Close","notAttachedLabel":"Not attached"}' where not exists (select 1 from public.content_translations where content_id = '3f39c119-6448-54a2-a488-018088a76a72' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select '3f39c119-6448-54a2-a488-018088a76a72','ar','الوظائف','{"eyebrow":"الوظائف والتدريب","title":"الوظائف","introduction":"في شركة FBS للمقاولات، ندرك أهمية الكفاءات البشرية في تقديم خدمات إنشائية عالية الجودة. ونؤمن بقيم الاحترافية والتعاون والتطوير المستمر، ونسعى إلى بناء مستقبل أقوى من خلال كوادر مؤهلة وطموحة.","opportunitiesTitle":"الفرص الوظيفية","noVacanciesTitle":"اكتشف الفرص المهنية معنا","noVacanciesDescription":"سيتم عرض الوظائف المتاحة هنا عند الإعلان عنها. ويمكنك أيضًا تجهيز طلب تقديم عام من خلال النموذج التالي.","formTitle":"نموذج التقديم على وظيفة","formDescription":"عرّفنا بنفسك وشاركنا خبراتك ومؤهلاتك المهنية.","nameLabel":"الاسم بالكامل","emailLabel":"البريد الإلكتروني","subjectLabel":"الموضوع","messageLabel":"رسالتك","cvLabel":"إرفاق السيرة الذاتية","submitLabel":"مراجعة الطلب","demoNotice":"هذا نموذج تجريبي فقط، ولا يتم إرسال الطلبات أو تخزينها في المرحلة الحالية.","cvHint":"ملف PDF أو DOC أو DOCX — بحد أقصى 5 ميجابايت","invalidCvType":"يرجى اختيار ملف PDF أو DOC أو DOCX.","invalidCvSize":"يجب ألا يتجاوز حجم الملف 5 ميجابايت.","reviewTitle":"مراجعة طلب التقديم","closeLabel":"إغلاق","notAttachedLabel":"لم يتم إرفاق ملف"}' where not exists (select 1 from public.content_translations where content_id = '3f39c119-6448-54a2-a488-018088a76a72' and language_code = 'ar') on conflict do nothing;
