insert into public.content_translations (content_id,language_code,title,content) select 'edf64691-613f-5186-a3de-611f83d49aca','en','Training','{"eyebrow":"Careers & Training","title":"Training","leadTitle":"Investing in People and Skills","introduction":"At FBS Contracting, developing people is an important part of our commitment to quality and continuous improvement. We recognize the value of competent, well-trained, and engaged employees, while supporting local skills development in line with Saudi Vision 2030.","visualEyebrow":"PEOPLE & DEVELOPMENT","visualTitle":"Building Skills for a Stronger Future","prioritiesTitle":"Our People Development Priorities","priorities":[{"title":"Local Skills Development","description":"As part of our commitment to Saudi Vision 2030, we support local employment and skills development to contribute to the Kingdom’s long-term progress."},{"title":"Employee Competence","description":"Our Quality Management Policy emphasizes the importance of competent, well-trained, and engaged employees in maintaining and improving our operations."},{"title":"Safety Participation","description":"Our Occupational Health and Safety Policy emphasizes worker consultation and participation in planning, evaluating, and improving workplace safety."}],"closing":"We believe that developing people, supporting competence, and encouraging active participation contribute to a stronger organization."}' where not exists (select 1 from public.content_translations where content_id = 'edf64691-613f-5186-a3de-611f83d49aca' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select 'edf64691-613f-5186-a3de-611f83d49aca','ar','التدريب','{"eyebrow":"الوظائف والتدريب","title":"التدريب","leadTitle":"الاستثمار في الإنسان وتنمية المهارات","introduction":"في شركة FBS للمقاولات، يمثل تطوير الكوادر البشرية جزءًا مهمًا من التزامنا بالجودة والتحسين المستمر. ونؤمن بأهمية الموظفين المؤهلين والمدربين والمشاركين بفاعلية في العمل، مع دعم تنمية المهارات المحلية بما يتماشى مع رؤية السعودية 2030.","visualEyebrow":"الكوادر البشرية والتطوير","visualTitle":"نبني المهارات لمستقبل أقوى","prioritiesTitle":"أولوياتنا في تطوير الكوادر البشرية","priorities":[{"title":"تنمية المهارات المحلية","description":"في إطار التزامنا برؤية السعودية 2030، ندعم التوظيف المحلي وتنمية المهارات للمساهمة في التنمية طويلة الأمد بالمملكة."},{"title":"تأهيل الموظفين","description":"تؤكد سياسة إدارة الجودة لدينا أهمية وجود موظفين مؤهلين ومدربين ومشاركين بفاعلية في الحفاظ على العمليات وتحسينها."},{"title":"المشاركة في السلامة المهنية","description":"تؤكد سياسة الصحة والسلامة المهنية أهمية التشاور مع العاملين ومشاركتهم في تخطيط وتقييم وتحسين بيئة العمل والسلامة المهنية."}],"closing":"نؤمن بأن تطوير الكوادر البشرية وتعزيز الكفاءة وتشجيع المشاركة الفعالة يساهم في بناء مؤسسة أكثر قوة واستدامة."}' where not exists (select 1 from public.content_translations where content_id = 'edf64691-613f-5186-a3de-611f83d49aca' and language_code = 'ar') on conflict do nothing;
