insert into public.content_translations (content_id,language_code,title,content) select 'ce7d0044-0a17-557e-a4f0-0f2a92e951e7','en','Supplier Registration','{"eyebrow":"Business Partnerships","title":"Supplier Registration","introduction":"At FBS Contracting, we recognize the importance of strong and collaborative relationships with suppliers and business partners. We welcome opportunities to connect with companies offering products and services relevant to the construction industry.","formTitle":"Supplier Information","formDescription":"Share your company information and area of specialization using the form below.","companyNameLabel":"Company Name","contactNameLabel":"Contact Person","emailLabel":"Business Email","phoneLabel":"Phone Number","categoryLabel":"Business Category","categoryPlaceholder":"Select a Category","notesLabel":"Company Overview","profileLabel":"Attach Company Profile","profileHint":"PDF, DOC or DOCX — Maximum 5 MB","categories":[{"value":"materials","label":"Construction Materials"},{"value":"subcontracting","label":"Subcontracting"},{"value":"equipment","label":"Equipment & Machinery"},{"value":"services","label":"Professional Services"},{"value":"other","label":"Other"}],"submitLabel":"Review Registration","reviewTitle":"Review Supplier Information","closeLabel":"Close","notAttachedLabel":"Not attached","invalidPhone":"Enter 8–15 digits. Use only spaces, hyphens, parentheses and an optional leading +.","invalidFileType":"Please select a PDF, DOC or DOCX file.","invalidFileSize":"The file must not exceed 5 MB.","demoNotice":"Demo form only. Supplier information is not submitted or stored at this stage."}' where not exists (select 1 from public.content_translations where content_id = 'ce7d0044-0a17-557e-a4f0-0f2a92e951e7' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,content) select 'ce7d0044-0a17-557e-a4f0-0f2a92e951e7','ar','تسجيل الموردين','{"eyebrow":"شراكات الأعمال","title":"تسجيل الموردين","introduction":"تؤمن شركة FBS للمقاولات بأهمية بناء علاقات قوية وتعاونية مع الموردين وشركاء الأعمال. ونرحب بالتواصل مع الشركات التي تقدم المنتجات والخدمات المرتبطة بقطاع البناء والتشييد.","formTitle":"بيانات المورد","formDescription":"شاركنا معلومات شركتك ومجال تخصصها من خلال النموذج التالي.","companyNameLabel":"اسم الشركة","contactNameLabel":"اسم مسؤول التواصل","emailLabel":"البريد الإلكتروني للشركة","phoneLabel":"رقم الهاتف","categoryLabel":"مجال النشاط","categoryPlaceholder":"اختر مجال النشاط","notesLabel":"نبذة عن الشركة","profileLabel":"إرفاق الملف التعريفي للشركة","profileHint":"ملف PDF أو DOC أو DOCX — بحد أقصى 5 ميجابايت","categories":[{"value":"materials","label":"مواد البناء"},{"value":"subcontracting","label":"مقاولات الباطن"},{"value":"equipment","label":"المعدات والآلات"},{"value":"services","label":"الخدمات المهنية"},{"value":"other","label":"أخرى"}],"submitLabel":"مراجعة بيانات التسجيل","reviewTitle":"مراجعة بيانات المورد","closeLabel":"إغلاق","notAttachedLabel":"لم يتم إرفاق ملف","invalidPhone":"أدخل من 8 إلى 15 رقمًا. يُسمح بالمسافات والشرطات والأقواس وعلامة + واحدة في البداية.","invalidFileType":"يرجى اختيار ملف PDF أو DOC أو DOCX.","invalidFileSize":"يجب ألا يتجاوز حجم الملف 5 ميجابايت.","demoNotice":"هذا نموذج تجريبي فقط، ولا يتم إرسال بيانات الموردين أو تخزينها في المرحلة الحالية."}' where not exists (select 1 from public.content_translations where content_id = 'ce7d0044-0a17-557e-a4f0-0f2a92e951e7' and language_code = 'ar') on conflict do nothing;
