insert into public.content_translations (content_id,language_code,title,summary,content) select '2a1f7f58-1027-582d-a839-5e431cc50030','en','Building with purpose.','Delivering residential and commercial developments across Saudi Arabia through quality, reliability and a commitment to long-term value.','{"imageAlt":"Jawhart Al-Sahab residential architecture in Riyadh","statistics":{"heading":"FBS Contracting in numbers","approvalNotice":"Demo figures from the existing company artwork. Pending official client approval.","thousand":"K","billion":"B","currencyUnit":"SAR","labels":{"projectValue":"Project value","residentialProjects":"Residential projects","residentialUnits":"Residential units","builtUpArea":"Built-up area","commercialProjects":"Commercial projects","concreteWorks":"Concrete works","employees":"Employees"}},"eyebrow":"FBS Contracting","titleLine1":"Building with","titleLine2":"purpose.","description":"Delivering residential and commercial developments across Saudi Arabia through quality, reliability and a commitment to long-term value.","primaryCta":"Explore Projects","secondaryCta":"Discover FBS","location":"Kingdom of Saudi Arabia"}' where not exists (select 1 from public.content_translations where content_id = '2a1f7f58-1027-582d-a839-5e431cc50030' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,summary,content) select '2a1f7f58-1027-582d-a839-5e431cc50030','ar','نبني برؤية تصنع المستقبل','نقدم مشاريع سكنية وتجارية في المملكة العربية السعودية بجودة وموثوقية والتزام بقيمة طويلة الأمد.','{"imageAlt":"عمارة مشروع جوهرة السحاب السكني في الرياض","statistics":{"heading":"FBS للمقاولات بالأرقام","approvalNotice":"أرقام توضيحية من التصميم الحالي للشركة، بانتظار الاعتماد الرسمي من العميل.","thousand":"ألف","billion":"مليار","currencyUnit":"ر.س","labels":{"projectValue":"قيمة المشاريع","residentialProjects":"مشاريع سكنية","residentialUnits":"وحدات سكنية","builtUpArea":"مساحة البناء","commercialProjects":"مشاريع تجارية","concreteWorks":"الأعمال الخرسانية","employees":"العاملون"}},"eyebrow":"FBS للمقاولات","titleLine1":"نبني برؤية","titleLine2":"تصنع المستقبل","description":"نقدم مشاريع سكنية وتجارية في المملكة العربية السعودية بجودة وموثوقية والتزام بقيمة طويلة الأمد.","primaryCta":"استكشف المشاريع","secondaryCta":"اكتشف FBS","location":"المملكة العربية السعودية"}' where not exists (select 1 from public.content_translations where content_id = '2a1f7f58-1027-582d-a839-5e431cc50030' and language_code = 'ar') on conflict do nothing;
