insert into public.content_translations (content_id,language_code,title,summary,content) select '196be20a-c2e9-5f10-a4ce-51482699f6e9','en','A Vision That Shapes Reality.','FBS Contracting Company is a leading construction company dedicated to delivering exceptional construction services. With a strong focus on quality, innovation, and client satisfaction, we have established ourselves as a trusted partner in the industry.','{"eyebrow":"Who We Are","titleLine1":"A Vision That","titleLine2":"Shapes Reality.","description":"FBS Contracting Company is a leading construction company dedicated to delivering exceptional construction services. With a strong focus on quality, innovation, and client satisfaction, we have established ourselves as a trusted partner in the industry.","secondaryText":"We understand that every project is unique. Our commitment to excellence, safety, and close collaboration with clients guides us in bringing their visions to life.","cta":"Learn More About FBS"}' where not exists (select 1 from public.content_translations where content_id = '196be20a-c2e9-5f10-a4ce-51482699f6e9' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,summary,content) select '196be20a-c2e9-5f10-a4ce-51482699f6e9','ar','رؤية تصنع واقعًا','شركة FBS للمقاولات هي شركة إنشاءات رائدة متخصصة في تقديم خدمات بناء استثنائية. مع التركيز القوي على الجودة والابتكار ورضا العملاء، أثبتنا مكانتنا كشريك موثوق في قطاع المقاولات والتشييد.','{"eyebrow":"من نحن","titleLine1":"رؤية تصنع","titleLine2":"واقعًا","description":"شركة FBS للمقاولات هي شركة إنشاءات رائدة متخصصة في تقديم خدمات بناء استثنائية. مع التركيز القوي على الجودة والابتكار ورضا العملاء، أثبتنا مكانتنا كشريك موثوق في قطاع المقاولات والتشييد.","secondaryText":"ندرك أن كل مشروع فريد من نوعه، ونعمل بالتزام بالتميز والسلامة والتعاون الوثيق مع عملائنا لتحقيق رؤيتهم على أرض الواقع.","cta":"تعرف على FBS للمقاولات"}' where not exists (select 1 from public.content_translations where content_id = '196be20a-c2e9-5f10-a4ce-51482699f6e9' and language_code = 'ar') on conflict do nothing;
