insert into public.content_translations (content_id,language_code,title,summary,content) select '10584f7e-16c9-5483-a947-dbe71b02d312','en','From concept to completion.','We provide comprehensive services throughout the project lifecycle, from initial feasibility studies and concept design to construction works. Through partnerships with experts across disciplines, we offer an integrated approach to project planning and execution.','{"eyebrow":"Company Services","titleLine1":"From concept","titleLine2":"to completion.","description":"We provide comprehensive services throughout the project lifecycle, from initial feasibility studies and concept design to construction works. Through partnerships with experts across disciplines, we offer an integrated approach to project planning and execution.","items":["Feasibility Study","Land Development","Design Management","Construction Works","Maintenance & Operations"]}' where not exists (select 1 from public.content_translations where content_id = '10584f7e-16c9-5483-a947-dbe71b02d312' and language_code = 'en') on conflict do nothing;
insert into public.content_translations (content_id,language_code,title,summary,content) select '10584f7e-16c9-5483-a947-dbe71b02d312','ar','خدمات متكاملة من الفكرة إلى التنفيذ','نقدم خدمات شاملة طوال دورة حياة المشروع، بدءًا من دراسة الجدوى الأولية وتصميم المفهوم وحتى أعمال البناء. ومن خلال شراكاتنا مع خبراء في مختلف التخصصات، نقدم نهجًا متكاملًا يضمن التنسيق والتنفيذ الفعال للمشاريع.','{"eyebrow":"خدمات الشركة","titleLine1":"خدمات متكاملة","titleLine2":"من الفكرة إلى التنفيذ","description":"نقدم خدمات شاملة طوال دورة حياة المشروع، بدءًا من دراسة الجدوى الأولية وتصميم المفهوم وحتى أعمال البناء. ومن خلال شراكاتنا مع خبراء في مختلف التخصصات، نقدم نهجًا متكاملًا يضمن التنسيق والتنفيذ الفعال للمشاريع.","items":["دراسة الجدوى","تطوير الأراضي","إدارة التصميم","أعمال البناء","أعمال الصيانة"]}' where not exists (select 1 from public.content_translations where content_id = '10584f7e-16c9-5483-a947-dbe71b02d312' and language_code = 'ar') on conflict do nothing;
