insert into public.content_translations (content_id,language_code,title,summary,content) select '5777e0fc-321e-5397-a7c8-7bc1a309135e','en','Values that guide how we build.','Discover the six core values that guide FBS Contracting.','{"eyebrow":"Our Values","titleLine1":"Values that guide","titleLine2":"how we build.","description":"Discover the six core values that guide FBS Contracting.","items":{"integrity":{"title":"Integrity","description":"We work with transparency, accountability and respect in every relationship."},"quality":{"title":"Quality","description":"We maintain a consistent focus on high standards across every stage of delivery."},"collaboration":{"title":"Collaboration","description":"We bring teams, disciplines and partners together around shared project goals."},"responsibility":{"title":"Responsibility","description":"We approach every project with care for people, communities and long-term impact."}}}' where not exists (select 1 from public.content_translations where content_id = '5777e0fc-321e-5397-a7c8-7bc1a309135e' and language_code = 'en') on conflict do nothing;
